# Typed lowered IR -> C source, one concrete MethodInstance at a time.
#
# Walks the *unoptimized* typed CodeInfo (`code_typed(optimize=false)`): every value
# carries its inferred concrete type, local variable names survive, and arithmetic
# appears as calls to +, -, *, / rather than intrinsics. Julia locals become C locals
# named by the rules in `name.jl`; intermediate values become temps named by the rules
# on `temp!`. Operations on arrays become calls to helpers generated by `helper.jl`;
# control flow is recovered from gotos by `flow.jl`.

include("name.jl")
include("type.jl")
include("prose.jl")
include("helper.jl")
include("source.jl")

# State shared by every function in one output file.
mutable struct Program
    helpers::Dict{String, String}                                  # see helper.jl
    headers::Set{String}                                           # standard headers the output needs
    calls::Dict{Core.MethodInstance, String}                       # every transpiled instance -> its C name
    pending::Vector{Tuple{Core.MethodInstance, Vector{Type}, String}}   # found through a call, not generated yet
    names::Set{String}                                             # C function names taken so far
    foreign::Dict{String, String}                                  # a `ccall`ed symbol -> its prototype
    structs::Vector{Pair{Type, String}}                            # struct typedefs, dependencies first
    precise::Bool                                                  # print every digit of a floating value, not `%g`
    width::Int                                                     # the longest line; scalar expressions wrap past it
    suffix::Bool                                                   # temps carry what they were computed from: `temp1_a_b`
    returned::Dict{Core.MethodInstance, Union{String, Nothing}}    # the variable a user function returns, if it returns one (`returnname!`)
    effects::Dict{Core.MethodInstance, Set{Symbol}}                # what a user function does besides compute (see `effects!`)
    kinds::Dict{Core.MethodInstance, Any}                          # the C struct a tuple-returning function returns (see `returnkind!`)
    tupledefs::Vector{Pair{String, String}}                        # those typedefs, name => text
    globals::Vector{Any}                                           # the program's global variables, in order (see `global!`)
    exported::Set{String}                                          # helpers asked for by name, written as functions of the user's
    # Every file-scope name the author's own things asked for, and got (`claim!`); and, on a
    # build done again because the first gave a name to the wrong one (`audit`), the names
    # settled beforehand and the names to keep clear of.
    claims::Vector{Any}
    fixed::Dict{Any, String}
    avoid::Set{String}
    written::Set{Any}                                              # globals some function writes into, as (module, name): not `const` in C
    yielded::Set{String}                                           # names of the author's that a name of ours (a macro, a tuple's struct) keeps clear of
    walking::Any                                                   # the `Scope` of the function being written, for saying where a refusal happened
end

# A global variable in the output: its C name, the Julia binding it came from (module and
# name; the module is `nothing` for a value listed with no binding behind it), its
# value, and whether the C declares it `const`.
struct Global
    cname::String
    mod::Union{Module, Nothing}
    name::Symbol
    value
    constant::Bool
end

# How a tuple is laid out in C: the struct's name and its field names — `step_t` with
# `x` and `xdot` for `return x, ẋ` in `step` — or, with an empty name, a tuple spread
# into separate C variables (a tuple parameter becomes parameters `t1`, `t2`, …).
struct Kind
    cname::String
    fields::Vector{String}
end
Program(; precise::Bool=false, width::Integer=100, suffix::Bool=true) =
    Program(Dict{String, String}(), Set(["stdint.h", "stdbool.h"]), Dict{Core.MethodInstance, String}(),
            Tuple{Core.MethodInstance, Vector{Type}, String}[], Set{String}(), Dict{String, String}(), Pair{Type, String}[], precise, width,
            suffix, Dict{Core.MethodInstance, Union{String, Nothing}}(), Dict{Core.MethodInstance, Set{Symbol}}(), Dict{Core.MethodInstance, Any}(), Pair{String, String}[], Any[], Set{String}(),
            Any[], Dict{Any, String}(), Set{String}(), Set{Any}(), Set{String}(), nothing)

# The irrationals the current `transpile` call has met, by the macro each is written as:
# `"LEGIBLEC_PI" => π`. The helper header defines the ones the output uses.
const irrationals = Dict{String, Any}()
const macroavoid = Set{String}()        # names of the author's that a macro must keep clear of

# One C block of a function: the function's own body, a loop's body, a branch of an `if`.
# `lo:hi` are the statements emitted inside its braces. What is declared in a loop's body
# is made anew on every pass.
struct Block
    lo::Int
    hi::Int
    parent::Int     # 0 for the function's own
    depth::Int
    loop::Bool
end

# Per-function state.
mutable struct Scope
    ci::Core.CodeInfo
    names::Vector{String}               # C name of each slot (index 1 is `#self#`, unused)
    result::String                      # name for an unnamed result, `result` unless that's taken
    resultname::String                  # the same, kept after `result` is claimed
    resultparam::Bool                   # the result is an array, passed out through a parameter
    limit::Int                          # longest temp name we're willing to mangle to
    blocked::Set{Int}                   # temp numbers already taken by the user's own names
    counter::Int
    expr::Dict{Int, String}             # SSA id -> the C expression that stands for it
    helpers::Dict{String, String}       # shared across the whole output; see helper.jl
    headers::Set{String}                # shared: standard headers the output needs
    # Sizes the IR doesn't know: a regular array's type has none, so the transpiler
    # tracks a shaped stand-in for each SSA value and slot that holds one.
    shapes::Dict{Int, Type}             # SSA id -> shaped type
    slotshapes::Dict{Int, Type}         # slot id -> shaped type
    rettype::Type                       # the (shaped) type actually returned
    # Source annotations (see source.jl): the file, each statement's line, how far
    # into the file the comments have been emitted, and whether code lines are copied.
    src::Union{Source, Nothing}
    stmtline::Vector{Int}
    cursor::Int
    copycode::Bool
    # Control flow (see flow.jl).
    depth::Int                          # current nesting, for indentation
    inlined::Set{Int}                   # SSA ids rendered inside conditions, not as temps
    skipped::Set{Int}                   # statements consumed by a construct; never emitted
    hidden::Set{Int}                    # slots never declared: iterator state, loop variables, aliases
    mutated::Set{Int}                   # array slots written through setindex!
    fors::Dict{Int, Any}
    whiles::Dict{Int, Any}
    prog::Program
    # Step comments (see `step!`): each is (first line, last line, text, Julia line).
    steps::Vector{Tuple{Int, Int, String, Int}}
    current::Int                        # the statement being emitted
    math::Dict{Int, String}             # SSA id -> the math a rendered helper call computes
    # An array parameter Julia reassigns: its working copy's slot -> the parameter's
    # slot. The copy is made at the top of the function, under a comment saying why.
    rebound::Dict{Int, Int}
    declared::Set{Int}                  # slots already declared, at their first assignment
    starts::Vector{Int}                 # per depth: the line where the statement or construct now being emitted there began
    # Lines to insert once the walk is done, (at, priority, text or () -> text): hoisted
    # declarations and the comments that go above a multi-line step. Deferred so that
    # nothing shifts under the line numbers recorded along the way.
    inserts::Vector{Tuple{Int, Int, Any}}
    # Array negations folded into the scalar of the multiply or divide that consumes
    # them: `-x / s` is `div_3_s(x, -s, …)`. The SSA value reads as the array itself.
    negated::Set{Int}
    # `sincos(x)`: the SSA value stands for the pair `("sin(x)", "cos(x)")`, read out by
    # destructuring; it has no C value of its own.
    pair::Dict{Int, Tuple{String, String}}
    kind::Union{Kind, Nothing}          # this function's returned tuple, if it returns one
    kinds::Dict{Int, Kind}              # SSA values holding a tuple of a known layout
    slotkinds::Dict{Int, Kind}          # slots likewise; a spread parameter has an empty cname
    placed::Dict{Int, String}           # a construction whose destination a field's value was computed into, already declared (`placement`)
    known::Dict{Int, Any}               # SSA values the transpiler knows as constants that Julia didn't: `end` of a sized regular array, a range of such
    outplaced::Dict{Int, Int}           # array slots that live in `out` from the start, slot -> offset (`outplacement!`)
    pointers::Set{String}               # C names that are pointers, not arrays: `sizeof` needs the type spelled out
    # The C blocks, in the order they are opened (the function's body is 1), the ones open
    # now, and the block each variable is declared in (`homes`), known from a first walk.
    blocks::Vector{Block}
    path::Vector{Int}
    home::Dict{Int, Int}
    # What the first walk wrote, line by line with the block it went into, and the header
    # of each loop; and the file-scope names the function mentions (`names!`).
    emitted::Vector{Tuple{Int, String}}
    headline::Dict{Int, String}
    pending::String
    outer::Set{String}
    lets::Dict{Int, Vector{NTuple{3, Int}}}   # the source's `let` blocks: first statement -> (first, last, the `let` line), outermost first
    tree::Any                           # the control flow, recovered and checked before anything is written (`tree.jl`)
    choices::Dict{Int, Any}             # `a && b`, `a || b`, `c ? x : y` as values, by the statement that reads one (`choice.jl`)
    folded::Set{Int}                    # jumps of a test Julia has already decided: no C, and no branch
    alias::Dict{Int, Any}               # a read of a variable of Julia's own making that is just what was stored in it -> that value
end

function Scope(ci::Core.CodeInfo, mi::Core.MethodInstance, sig, limit::Integer, prog::Program, copycode::Bool)
    names = ["#self#"; identifiers([isempty(string(s)) ? "#s$i" : string(s) for (i, s) in enumerate(ci.slotnames[2:end])])]
    hidden = Set{Int}(i for (i, s) in enumerate(ci.slotnames) if i > 1 && isempty(string(s)))
    result = "result"
    while result in names
        result *= "_"
    end
    blocked = Set{Int}()
    for s in names
        m = match(r"^temp(\d+)(_.*)?$", s)
        m === nothing || push!(blocked, parse(Int, m[1]))
    end
    slotshapes = Dict{Int, Type}(i + 1 => T for (i, T) in enumerate(sig) if isarray(T))
    src = Source(mi.def)
    stmtline = statementlines(mi, length(ci.code))   # from the IR, so it works without the file
    return Scope(ci, names, result, result, false, limit, blocked, 0, Dict{Int, String}(), prog.helpers, prog.headers,
                 Dict{Int, Type}(), slotshapes, Union{}, src, stmtline, src === nothing ? 0 : src.first - 1, copycode,
                 0, Set{Int}(), Set{Int}(), hidden, Set{Int}(), Dict{Int, Any}(), Dict{Int, Any}(), prog,
                 Tuple{Int, Int, String, Int}[], 0, Dict{Int, String}(), Dict{Int, Int}(), Set{Int}(), Int[1],
                 Tuple{Int, Int, Any}[], Set{Int}(), Dict{Int, Tuple{String, String}}(), nothing, Dict{Int, Kind}(), Dict{Int, Kind}(), Dict{Int, String}(), Dict{Int, Any}(), Dict{Int, Int}(), Set{String}(),
                 Block[], Int[], Dict{Int, Int}(), Tuple{Int, String}[], Dict{Int, String}(), "", Set{String}(), Dict{Int, Vector{NTuple{3, Int}}}(), nothing, Dict{Int, Any}(), Set{Int}(), Dict{Int, Any}())
end

include("flow.jl")
include("io.jl")
include("move.jl")

"""
    cfunction(name, mi, sig, helpers, headers; templimit=40, source=true) -> (prototype, definition)

C source for the concrete MethodInstance `mi`, named `name` in C, with argument types
`sig` — the instance's own types, except that a regular array is given as a shaped
stand-in carrying the size the IR doesn't know. Any array helpers it needs are added
to `helpers`, and any standard headers to `headers`.
"""
function cfunction(name::AbstractString, mi::Core.MethodInstance, sig, prog::Program;
                   templimit::Integer=40, source::Bool=true)
    # The one way out for whatever can't be written. Thrown again from outside the `catch`,
    # so that what Julia prints under it is the way in from `transpile`, and not the
    # transpiler's insides.
    prog.walking = nothing
    local made
    problem = try
        made = compose(name, mi, sig, prog, templimit, source)
        nothing
    catch e
        e isa InterruptException && rethrow()
        e isa ArgumentError || e isa Fault || (failure[] = (e, catch_backtrace()))
        e
    end
    problem === nothing && return made
    throw(explained(problem, mi, prog.walking))
end

"""
    Fault

Something the transpiler got wrong itself. A refusal, an `ArgumentError`, is about the Julia
it was given, and says what to write instead; a `Fault` is about the transpiler, says which
function and line it was working on, and asks to be reported. The error underneath, with
its stack, is kept in `LegibleC.failure[]`.
"""
struct Fault <: Exception
    msg::String
end
Base.showerror(io::IO, e::Fault) = print(io, e.msg)
const failure = Ref{Any}(nothing)

# What went wrong, in the author's terms: the function, the file and line, and the line
# itself. A statement's number, which many messages carry, means nothing to the author; it
# is how the line is found, and then it is dropped.
function explained(e, mi::Core.MethodInstance, sc)
    e isa Fault && return e
    def = mi.def
    msg = e isa ArgumentError ? e.msg : sprint(showerror, e)
    line = 0
    if sc !== nothing
        m = match(r"\(statement (\d+)", msg)
        m === nothing || (line = get(sc.stmtline, parse(Int, m[1]), 0))
        line == 0 && (m = match(r"\bline (\d+)", msg)) !== nothing && (line = parse(Int, m[1]))
        line == 0 && sc.current > 0 && (line = sc.stmtline[sc.current])
    end
    line == 0 && (line = def.line)
    text = sc !== nothing && sc.src !== nothing && line in eachindex(sc.src.lines) ? strip(sc.src.lines[line]) : ""
    where = "`$(def.name)`, $(basename(string(def.file))):$line" * (isempty(text) ? "" : ":  " * text)
    e isa ArgumentError && return ArgumentError(replace(msg, r" \(statement \d+[^)]*\)" => "") * "\n  in " * where)
    return Fault("the transpiler went wrong in " * where * "\n  " * msg *
                 "\nThis is a mistake of LegibleC's, not of the Julia. Please report it with the function above; `LegibleC.failure[]` holds the error and its stack.")
end

function compose(name::AbstractString, mi::Core.MethodInstance, sig, prog::Program, templimit::Integer, source::Bool)
    ci, rettype = only(Base.code_typed_by_type(mi.specTypes; optimize=false))
    # A function that never returns, because every path through it throws, is `_Noreturn void` in C (`finish`).
    rettype = rettype === Union{} ? Nothing : returntype(mi)                # one C type: numbers settled, anything else refused by line
    # The function is walked twice. The first walk is only to learn its C blocks, which
    # the `if`s reveal as they are emitted, and from them where each variable is declared
    # (`homes`); the second writes the C. Emission is repeatable, so the blocks agree.
    first = ready(name, mi, sig, prog, rettype, templimit, source, nothing)
    walk!(String[], first)
    first.home = homes(first)
    # A variable the walk never declared — assigned only where it doesn't look — is declared
    # at the top of the function (`finish`), so the top is where it lives, for its name too.
    for s in ci.nargs+1:length(ci.slotnames)
        s in first.declared || s in first.hidden || (first.home[s] = 1; push!(first.emitted, (1, try slotdecl(first, s) catch; "" end)))
    end
    sc = ready(name, mi, sig, prog, rettype, templimit, source, first)
    sc.home = first.home
    ci = sc.ci

    # The signature line's own comment comes before the prologue of copies; a short-form
    # definition's line is its body, so that comment stays with the body.
    head = String[]
    sc.src !== nothing && !sc.src.short && annotate!(head, sc, sc.src.first)
    body = String[]
    walk!(body, sc)
    return finish(name, mi, sc, head, body)
end

# Emit the whole body, as the function's own block.
function walk!(body, sc::Scope)
    n = length(sc.ci.code)
    push!(sc.blocks, Block(1, n, 0, 0, false))
    push!(sc.path, 1)
    block!(body, sc, 1, n)
    pop!(sc.path)
end

# A function's state, ready to be walked: its types and names settled, its loops found.
function ready(name, mi::Core.MethodInstance, sig, prog::Program, rettype, templimit, source, first)
    ci, _ = only(Base.code_typed_by_type(mi.specTypes; optimize=false))
    sc = Scope(ci, mi, sig, templimit, prog, source)
    prog.walking = sc
    if first === nothing
        # The first walk names every variable unmistakably, `v5__omega`, so that its text
        # shows, block by block, which variables and which outer names are mentioned.
        for i in 2:length(sc.names)
            isempty(string(ci.slotnames[i])) || (sc.names[i] = "v$(i)__" * sc.names[i])
        end
    else
        names!(sc, first)
    end
    sc.result = sc.resultname = free("result", union(sc.names, sc.outer))
    sc.blocked = Set(parse(Int, m[1]) for m in (match(r"^temp(\d+)(_.*)?$", s) for s in sc.names) if m !== nothing)
    sc.resultparam = isarray(rettype)
    sc.rettype = rettype
    istuple(sc.rettype) && (sc.kind = returnkind!(prog, mi, name))
    # A tuple parameter is spread into one parameter per element: `t1`, `t2`, …
    for i in 2:ci.nargs
        istuple(slottype(sc, i)) && (sc.slotkinds[i] = Kind("", [sc.names[i] * string(k) for k in 1:length(slottype(sc, i).parameters)]))
    end
    # The typedefs the signature needs. A tuple is spread (a parameter) or has its own
    # struct (the return, `returnkind!`), so only its element types need one.
    for T in [sig; sc.rettype]
        istuple(T) ? foreach(P -> structdef!(prog, P), T.parameters) : structdef!(prog, T)
    end
    if sc.resultparam
        # An array comes out through a parameter, and an output parameter is `out` —
        # `result` is kept for a returned scalar (see naming.md).
        sc.result = sc.resultname = free("out", union(sc.names, sc.outer))
    end
    analyze!(sc)
    sc.lets = findlets(sc)
    sc.tree = recover(sc)
    # `return a` from every exit — or `a = …` as the last line — with `a` a local of the
    # author's living in `out` from the start: then the out parameter is `a` itself.
    s = returnedslot(ci)
    if sc.resultparam && s !== nothing && get(sc.outplaced, s, -1) == 0 && !haskey(sc.rebound, s) && count(==(sc.names[s]), sc.names) == 1
        sc.result = sc.resultname = sc.names[s]
    end
    return sc
end

# The walked body, made into the function: comments, declarations, the prologue of copies,
# the signature and its documentation.
function finish(name, mi::Core.MethodInstance, sc::Scope, head, body)
    ci = sc.ci
    prog = sc.prog
    if sc.src !== nothing && sc.src.last > sc.cursor   # whatever follows the last statement
        separate!(body, sc)
        annotate!(body, sc, sc.src.last)
    end
    steps!(body, sc)
    # Hoisted declarations and above-the-line comments go in last, from the bottom up so
    # that nothing shifts; at one place a declaration comes first, then its copy, then a
    # step comment.
    for (at, _, text) in sort(sc.inserts; by=t -> (-t[1], -t[2]))
        insert!(body, at, text isa String ? text : text())
    end
    # A statement's blank line never sits against the closing brace of its block.
    body = [l for (k, l) in enumerate(body) if !(isempty(l) && (k == length(body) || startswith(lstrip(body[k+1]), "}")))]
    # Anything not declared along the way (a variable assigned only where the walk
    # doesn't look, such as a loop header) is declared at the top.
    # Nor one assigned only where control never goes, `if typemax(Float64) == 0.0; y = …; end`:
    # Julia gives it no type, and nothing that is written mentions it.
    lines = [slotdecl(sc, i) * ";" for i in ci.nargs+1:length(ci.slotnames) if !(i in sc.hidden) && !(i in sc.declared) && !(slottype(sc, i) in (Union{}, Nothing))]
    append!(lines, head)
    # Array parameters the function reassigns are worked on as copies, made here at
    # the top in one block with the reason above it, so the copy doesn't look gratuitous.
    # A copy that ends up in `out` is made there, and worked on there (`outplacement!`).
    listing(names) = length(names) == 1 ? names[1] :
                     length(names) == 2 ? names[1] * " and " * names[2] :
                     join(names[1:end-1], ", ") * ", and " * names[end]
    at(offset) = offset == 0 ? sc.resultname : "&$(sc.resultname)[$offset]"
    copies = sort([(s, p) for (s, p) in sc.rebound if !haskey(sc.outplaced, s)]; by=last)
    if !isempty(copies)
        push!(lines, "// copy $(listing([sc.names[p] for (_, p) in copies])) to prevent modification within this function")
        push!(sc.headers, "string.h")
        for (s, p) in copies
            push!(lines, declare(slottype(sc, s), sc.names[s]) * ";")
            push!(lines, "memcpy($(sc.names[s]), $(sc.names[p]), sizeof $(sc.names[s]));")
        end
        push!(lines, "")
    end
    inout = sort([(s, p) for (s, p) in sc.rebound if haskey(sc.outplaced, s)]; by=last)
    if !isempty(inout)
        them = length(inout) == 1 ? "it" : "them"
        push!(lines, "// copy $(listing([sc.names[p] for (_, p) in inout])) into $(sc.resultname), where the function works on $them and returns $them")
        push!(sc.headers, "string.h")
        for (s, p) in inout
            push!(lines, "memcpy($(at(sc.outplaced[s])), $(sc.names[p]), sizeof($(sizeof_(slottype(sc, s)))));")
            push!(lines, pointerdecl(slottype(sc, s), sc.names[s], at(sc.outplaced[s])) * ";")
        end
        push!(lines, "")
    end
    locals = sort([s for s in keys(sc.outplaced) if !haskey(sc.rebound, s) && sc.names[s] != sc.resultname]; by=s -> sc.outplaced[s])
    if !isempty(locals)
        push!(lines, "// $(listing([sc.names[s] for s in locals])) $(length(locals) == 1 ? "is" : "are") built in $(sc.resultname), where the function returns $(length(locals) == 1 ? "it" : "them")")
        for s in locals
            push!(lines, pointerdecl(slottype(sc, s), sc.names[s], at(sc.outplaced[s])) * ";")
        end
        push!(lines, "")
    end
    append!(lines, body)

    params = String[]
    for i in 2:ci.nargs
        T = slottype(sc, i)
        if haskey(sc.slotkinds, i)
            for (P, n) in zip(T.parameters, sc.slotkinds[i].fields)
                push!(params, declare(P, n; constant=isarray(P)))
            end
        else
            push!(params, declare(T, sc.names[i]; constant=isarray(T) && !(i in sc.mutated)))
        end
    end
    if sc.resultparam
        # C can't return an array; it comes out through a trailing parameter, which
        # takes the result's name.
        push!(params, declare(sc.rettype, sc.resultname; restrict=true))
        signature = "void $name($(join(params, ", ")))"
    else
        signature = "$(sc.kind === nothing ? declare(sc.rettype, name) : sc.kind.cname * " " * name)($(isempty(params) ? "void" : join(params, ", ")))"
    end
    # Every path through it throws: C11's word for that, so that a caller's `if` that ends in
    # a call to it is known to end there.
    only(Base.code_typed_by_type(mi.specTypes; optimize=false))[2] === Union{} && (signature = "_Noreturn " * signature)
    comments, doc = sc.src === nothing ? (String[], String[]) : leading(sc.src)
    origin = "$(mi.def.name)($(join(("$(ci.slotnames[i])::$(widen(ci.slottypes[i]))" for i in 2:ci.nargs), ", ")))" *
             (sc.src === nothing ? "" : " @$(sc.src.name):$(sc.src.first)")
    what(T) = isarray(T) ? describe(T) : T === Char ? "character" : T <: AbstractString ? "string" : T <: Number ? "scalar" : ""
    params = Tuple{String, String, String}[]
    for i in 2:ci.nargs
        if haskey(sc.slotkinds, i)
            for (P, n) in zip(slottype(sc, i).parameters, sc.slotkinds[i].fields)
                push!(params, ("in", n, what(P)))
            end
        else
            push!(params, (i in sc.mutated ? "in,out" : "in", sc.names[i], what(slottype(sc, i))))
        end
    end
    sc.resultparam && push!(params, ("out", sc.resultname, describe(sc.rettype) * ", the return value"))
    block = doxygen(doc, origin, params)
    # Four pieces: the prototype; what goes above it in the header (the leading comments
    # and the Doxygen block); the definition, for the `.c`; and the C names used.
    return signature * ";", join([comments; block], "\n"), join([signature * " {"; [isempty(l) ? l : "    " * l for l in lines]; "}"], "\n") * "\n", sc.names
end

# Everything that has to be known before emission starts: the loops, the statements
# they consume, the values rendered inline, mutated parameters, and slots that are
# only copies of another slot with the same name (a loop variable re-bound for an
# inner loop) — those take the original's name and vanish.
function analyze!(sc::Scope)
    ci = sc.ci
    code = ci.code
    foldstores!(sc)
    onetype!(sc)
    sc.fors = findfors(ci)
    for F in values(sc.fors)
        push!(sc.hidden, F.var)
        for i in F.start:F.bodylo-1; push!(sc.skipped, i); end
        for i in F.next:F.exit-1;    push!(sc.skipped, i); end
        for i in F.machinery;        push!(sc.skipped, i); end
    end
    sc.whiles = findwhiles(ci, sc.fors)
    # Statements consumed by the one that uses them: the pieces of a broadcast, and
    # the tuples that group constructor arguments.
    for (i, st) in enumerate(code)
        st isa Expr && st.head === :call || continue
        f = callee_or_nothing(ci, st.args[1])
        f === Base.broadcasted && push!(sc.skipped, i)
        # A tuple that only feeds a constructor or block construction is compile-time;
        # one that's a value in its own right becomes a struct.
        f === Core.tuple && consumed(ci, i) && push!(sc.skipped, i)
        # The `cconvert`/`unsafe_convert` pair a `ccall` wraps each argument in: no C.
        (f === Base.cconvert || f === Base.unsafe_convert) && push!(sc.skipped, i)
        # A factorization only ever feeds `\` or `inv`; the solver helper does both steps.
        (f === LinearAlgebra.cholesky || f === LinearAlgebra.lu) && push!(sc.skipped, i)
        # A `string(…)` or `repr(…)` that only feeds a print is printed piece by piece; so is
        # one that is the message of an exception, which is printed where it is thrown.
        printed(u) = (u = consumer(u); u isa Expr && u.head === :call && (g = callee_or_nothing(ci, u.args[1]); g in (Base.print, Base.println, Base.string, Base.repr, Base.error, Base._assert_tostring) || g isa Type && g <: Exception))
        (f === Base.string || f === Base.repr || f === Base._assert_tostring) && all(printed, (u for u in code if uses(u, i))) && push!(sc.skipped, i)
        # An exception is made to be thrown, and is written there (`throw!`): no C of its own.
        thrown(u) = (u = consumer(u); u isa Expr && u.head === :call && callee_or_nothing(ci, u.args[1]) === Core.throw)
        f isa Type && f <: Exception && all(thrown, (u for u in code if uses(u, i))) && push!(sc.skipped, i)
    end
    for (i, st) in enumerate(code)
        st isa Expr && st.head === :loopinfo &&
            throw(ArgumentError("`@simd` rewrites its loop into a form the transpiler doesn't read (line $(sc.stmtline[i])). Leave it out: it changes nothing the loop computes, and the C compiler vectorises the loop by itself"))
    end
    # A store into a typed global or a typed local, `global count += 1`, `local t::Float64`,
    # is lowered with a test before it: is the value already of that type? If not, convert.
    # Where Julia has decided the test, and it holds, the test and the conversion it guards
    # are no part of the C: what is left is the store.
    # Decided the other way, `x::Float64 = 1`, the conversion is what runs, and it is a cast.
    dead(k) = code[k] isa Core.Const || widen(ci.ssavaluetypes[k]) === Union{}
    for (g, st) in enumerate(code)
        st isa Core.GotoIfNot && st.cond isa Core.SSAValue && (c = code[st.cond.id]; c isa Expr && c.head === :call && callee_or_nothing(ci, c.args[1]) === Core.isa) || continue
        t = ci.ssavaluetypes[st.cond.id]
        t isa Core.Const && t.val isa Bool || continue
        push!(sc.skipped, st.cond.id, g)
        push!(sc.folded, g)
        # The jump over the dead conversion goes with it. Any other jump there is the author's,
        # `x isa Float64 && break`, and stays: it is now what always happens.
        # So does the jump over a dead `else`, which ends the branch that does run: `if n isa Int64 … else … end`.
        if t.val
            e = findlast(k -> !dead(k), g+1:st.dest-1)
            e === nothing || (e += g)
            e !== nothing && code[e] isa Core.GotoNode && code[e].label >= st.dest && all(dead, st.dest:code[e].label-1) && (push!(sc.skipped, e); push!(sc.folded, e))
        end
    end
    for (i, st) in enumerate(code)
        st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Core.get_binding_type && push!(sc.skipped, i)
    end
    # The keyword tuple of a `kwcall` — `(dims = 1,)`, built over a few statements — is
    # read at transpile time; none of it is C.
    function skipconstant!(x)
        x isa Core.SSAValue || return
        push!(sc.skipped, x.id)
        code[x.id] isa Expr && foreach(skipconstant!, code[x.id].args)
    end
    for st in code
        st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Core.kwcall && skipconstant!(st.args[2])
    end
    # The iterator state of `x, y = t` — `getfield(indexed_iterate(...), 2)`, usually
    # assigned to a hidden slot — has no C.
    for (i, st) in enumerate(code)
        ex = st isa Expr && st.head === :(=) ? st.args[2] : st
        ex isa Expr && ex.head === :call && callee_or_nothing(ci, ex.args[1]) === Core.getfield || continue
        ex.args[3] == 2 && ex.args[2] isa Core.SSAValue && iscall(code[ex.args[2].id], Base.indexed_iterate) || continue
        push!(sc.skipped, i)
        st isa Expr && st.head === :(=) && push!(sc.hidden, st.args[1].id)
    end
    for st in code
        ex = st isa Expr && st.head === :(=) ? st.args[2] : st
        ex isa Expr && ex.head === :call || continue
        f = callee_or_nothing(ci, ex.args[1])
        # What is written into: a variable, read directly or through a statement of its own
        # (as one assigned more than once is); or a global, whose `const` in Julia fixes
        # the binding and not the contents, so that in C it can't be `const` at all.
        globalof(a) = (a isa Core.SSAValue && (a = code[a.id]); a isa GlobalRef && getfield(a.mod, a.name) isa AbstractArray ? (a.mod, a.name) : nothing)
        if f in (Base.setindex!, Base.fill!, Base.materialize!)
            s = ex.args[2] isa Core.SlotNumber ? ex.args[2].id : slotof(sc, ex.args[2])
            s === nothing || push!(sc.mutated, s)
            g = globalof(ex.args[2])
            g === nothing || push!(sc.prog.written, g)
        end
        # A mutable array handed to a user function that writes somewhere: it may be
        # written there, so it is not `const` here either.
        f isa Function && !(nameof(Base.moduleroot(parentmodule(f))) in known) || continue
        slots = [a.id for a in ex.args[2:end] if a isa Core.SlotNumber && ci.slottypes[a.id] isa Type &&
                 ismutabletype(ci.slottypes[a.id]) && isarray(widen(ci.slottypes[a.id]))]
        globals = filter(!isnothing, [globalof(a) for a in ex.args[2:end]])
        isempty(slots) && isempty(globals) && continue
        r = userinstance!(sc, f, ex.args[2:end])
        r === nothing && continue
        isdisjoint(effects!(sc.prog, r[1]), (:write, :foreign, :unknown)) || (push!(sc.mutated, slots...); union!(sc.prog.written, globals))
    end
    assigned = Dict{Int, Vector{Int}}()
    for (i, st) in enumerate(code)
        st isa Expr && st.head === :(=) && push!(get!(assigned, st.args[1].id, Int[]), i)
    end
    # A parameter that is reassigned: Julia copies it into a fresh slot of the same name
    # at entry and reads that slot from then on. A scalar parameter is by value in C, so
    # the slot simply *is* the parameter, reassigned in place. An array parameter is the
    # caller's memory, so the slot is a working copy, `x_local`, made at the top of the
    # function (`cfunction`) — as Julia does, with a comment saying why.
    # Only Julia's own copy, which it makes on entry and after which the parameter is never
    # named again. `let x = x` and then `x += 1` has the same two statements, and there the
    # parameter is read again afterwards (or again on the next pass, in a loop): taking the
    # new `x` for the parameter itself wrote into the parameter. Julia 911, C 1215.
    entry(k) = all(j -> code[j] isa Core.NewvarNode || code[j] isa Expr && code[j].head === :(=) && code[j].args[2] isa Core.SlotNumber &&
                        2 <= code[j].args[2].id <= ci.nargs, 1:k)
    for (s, at) in assigned
        length(at) >= 2 && s > ci.nargs || continue
        rhs = code[at[1]].args[2]
        rhs isa Core.SSAValue && code[rhs.id] isa Core.SlotNumber && (rhs = code[rhs.id])
        rhs isa Core.SlotNumber && 2 <= rhs.id <= ci.nargs && ci.slotnames[s] == ci.slotnames[rhs.id] || continue
        entry(at[1]) && !any(j -> rhs.id in slotreads(code[j]) || rhs.id in slotwrites(code[j]), at[1]+1:length(code)) || continue
        # And only when it holds what the parameter holds. `n = n / 2` on an `Int64` parameter
        # makes the new `n` a `double`, which the `int64_t n` of the signature can't be: then it
        # is a variable of its own, `n_local`, by the ordinary rule for two things of one name.
        isarray(slottype(sc, s)) || slottype(sc, s) === slottype(sc, rhs.id) || continue
        push!(sc.skipped, at[1])
        if isarray(slottype(sc, s))
            sc.rebound[s] = rhs.id
            push!(sc.declared, s)
        else
            sc.names[s] = sc.names[rhs.id]
            push!(sc.declared, s)   # it is the parameter; nothing to declare
        end
    end
    for (s, at) in assigned
        length(at) == 1 || continue
        rhs = code[at[1]].args[2]
        rhs isa Core.SSAValue && code[rhs.id] isa Core.SlotNumber || continue
        t = code[rhs.id].id
        ci.slotnames[s] == ci.slotnames[t] || continue
        sc.names[s] = sc.names[t]
        push!(sc.hidden, s)
        push!(sc.skipped, at[1])
    end
    markinlined!(sc)
    # A variable of Julia's own making, stored once and read once with nothing in between
    # that does anything, is another name for what was stored: the lowering of a store into a
    # typed global or a typed local goes through one. The read is the value, written where
    # it is used, which is the move the inlining makes anyway.
    for s in ci.nargs+1:length(ci.slotnames)
        isempty(string(ci.slotnames[s])) && length(get(assigned, s, ())) == 1 || continue
        widen(ci.slottypes[s]) <: Number || continue
        p = assigned[s][1]
        V = code[p].args[2]
        # The value may sit on the store itself: `foldstores!` has put a call used once there.
        (V isa Number || V isa Core.SSAValue && V.id in sc.inlined && !haskey(sc.choices, V.id) ||
         V isa Expr && V.head === :call && pure(sc, V)) || continue
        live(r) = any(u -> uses(code[u], r) && !(u in sc.skipped), eachindex(code))
        reads = [r for r in eachindex(code) if code[r] isa Core.SlotNumber && code[r].id == s && live(r)]
        length(reads) == 1 && reads[1] > p || continue
        r = reads[1]
        users = [u for u in eachindex(code) if uses(code[u], r) && !(u in sc.skipped)]
        length(users) == 1 || continue
        # Into a plain store, of a variable or a global: nothing that writes its operand twice.
        u = code[users[1]]
        (u isa Expr && u.head === :(=) && u.args[2] == Core.SSAValue(r) || iscall(u, Core.setglobal!)) || continue
        all(k -> k in sc.skipped || silent(sc, k) || widen(ci.ssavaluetypes[k]) === Union{}, p+1:users[1]-1) || continue
        any(k -> code[k] isa Core.SlotNumber && code[k].id == s && k != r && live(k), eachindex(code)) && continue
        # A folded store leaves a copy of itself behind, `%p`, for a `return` to read: none may.
        all(k -> k == p + 1 && code[k] == Core.SSAValue(p), (k for k in eachindex(code) if uses(code[k], p))) || continue
        push!(sc.skipped, p)
        p < length(code) && code[p+1] == Core.SSAValue(p) && push!(sc.skipped, p + 1)
        push!(sc.inlined, r)
        sc.alias[r] = V isa Expr ? (p, V) : V
    end
    # A `while`'s test is the first that is its own, not that of a value its condition opens
    # with: `while (a || b) && n > 0`.
    past = Dict(c.test => c.join for c in values(sc.choices))
    for (h, W) in collect(sc.whiles)
        t = W.test
        while haskey(past, t)
            n = findfirst(k -> code[k] isa Core.GotoIfNot, past[t]+1:W.backedge)
            t = n === nothing ? 0 : past[t] + n
        end
        t in (0, W.test) || (sc.whiles[h] = While(W.header, t, W.backedge, W.exit))
    end
    outplacement!(sc)
end

callee_or_nothing(ci, x) = try callee(ci, x) catch; nothing end

# Append a line at the current nesting depth.
function emit!(lines, sc::Scope, s::AbstractString)
    isempty(sc.path) || push!(sc.emitted, (sc.path[end], s))
    push!(lines, "    "^sc.depth * s)
end

# Emit `prefix * expr * ";"`, wrapped when it would run past the program's width: the
# expression is split at the operators binding least tightly (outside parentheses and
# strings), and each continuation line starts with an operator, aligned under the
# expression's first operand.
function emitexpr!(lines, sc::Scope, prefix::AbstractString, expr::AbstractString)
    room = sc.prog.width - 4 * (sc.depth + 1)
    length(prefix) + length(expr) + 1 <= room && return emit!(lines, sc, prefix * expr * ";")
    # A long compound literal, `(Point){a, b}`: one field per line, as an initializer is
    # written by hand.
    m = match(r"^(\(\w+\)\{)(.*)\}$", expr)
    if m !== nothing
        fields = splitfields(m[2])
        emit!(lines, sc, prefix * m[1])
        for (k, f) in enumerate(fields)
            emit!(lines, sc, "    " * f * (k < length(fields) ? "," : ""))
        end
        return emit!(lines, sc, "};")
    end
    pieces = splitexpr(expr)
    # No operator to break at: a call breaks at its arguments' commas, the continuation
    # lines aligned under the first argument, as a long call is written by hand.
    if length(pieces) == 1 && (m = match(r"^([\w.]+\()(.*)\)$", expr)) !== nothing
        args = splitfields(m[2])
        length(args) > 1 || return emit!(lines, sc, prefix * expr * ";")
        pad = " " ^ (length(prefix) + length(m[1]))
        line = prefix * m[1] * args[1]
        for (k, a) in enumerate(args[2:end])
            more = ", " * a
            if length(line) + length(more) + (k == length(args) - 1 ? 2 : 1) > room
                emit!(lines, sc, line * ",")
                line = pad * a
            else
                line *= more
            end
        end
        return emit!(lines, sc, line * ");")
    end
    length(pieces) == 1 && return emit!(lines, sc, prefix * expr * ";")
    pad = " " ^ length(prefix)
    line = prefix * pieces[1]
    for k in 2:2:length(pieces)-1
        more = " " * pieces[k] * " " * pieces[k+1]
        if length(line) + length(more) + (k + 1 == length(pieces)) > room
            emit!(lines, sc, line)
            line = pad * pieces[k] * " " * pieces[k+1]
        else
            line *= more
        end
    end
    emit!(lines, sc, line * ";")
end

# `x = x + e` as `x += e`, and an integer's `x + 1` as `x++`: only when `e` is a whole
# operand at the top level, so `x = x + y - z` stays as written (`x += y - z` would be
# a different sum). Nothing if the statement isn't of that shape.
function compound(x::AbstractString, T::Type, text::AbstractString)
    occursin(" ? ", text) && return nothing       # `b * c ? p : q` is not `b *= c ? p : q`
    pieces = splitexpr(text)
    length(pieces) == 3 && pieces[1] == x && pieces[2] in ("+", "-", "*", "/") || return nothing
    pieces[3] == "1" && pieces[2] in ("+", "-") && T <: Integer && return x * pieces[2]^2
    return "$x $(pieces[2])= $(pieces[3])"
end

# The fields of an initializer's text, split at the commas outside any brackets.
function splitfields(text::AbstractString)
    out = String[]
    depth, start = 0, 1
    for (i, c) in enumerate(text)
        c in "([{" && (depth += 1)
        c in ")]}" && (depth -= 1)
        if c == ',' && depth == 0
            push!(out, strip(text[start:i-1]))
            start = i + 1
        end
    end
    push!(out, strip(text[start:end]))
    return out
end

# The top-level operands of `expr` interleaved with the operators between them, for
# whichever class of operator present binds least tightly: `["a", "+", "b * c", "-", "d"]`.
# Binary operators are rendered with a space on each side; nothing else in an
# expression sits between two spaces.
function splitexpr(expr::AbstractString)
    level = Dict("||" => 1, "&&" => 2, "|" => 3, "^" => 4, "&" => 5, "==" => 6, "!=" => 6, "<" => 7, "<=" => 7, ">" => 7, ">=" => 7,
                 "<<" => 8, ">>" => 8, "+" => 9, "-" => 9, "*" => 10, "/" => 10, "%" => 10)
    c = collect(expr)
    found = Tuple{Int, Int, String}[]     # (level, index of the operator's first character, operator)
    depth, instring, j = 0, false, 1
    while j <= length(c)
        ch = c[j]
        if instring
            ch == '\\' && (j += 1)
            ch == '"' && (instring = false)
        elseif ch == '"'
            instring = true
        elseif ch in "([{"
            depth += 1
        elseif ch in ")]}"
            depth -= 1
        elseif ch == ' ' && depth == 0
            k = something(findnext(==(' '), c, j + 1), length(c) + 1)
            tok = String(c[j+1:k-1])
            haskey(level, tok) && push!(found, (level[tok], j + 1, tok))
        end
        j += 1
    end
    isempty(found) && return [String(expr)]
    lowest = minimum(f[1] for f in found)
    pieces = String[]
    start = 1
    for (l, at, op) in found
        l == lowest || continue
        push!(pieces, String(c[start:at-2]))
        push!(pieces, op)
        start = at + length(op) + 1
    end
    push!(pieces, String(c[start:end]))
    return pieces
end

# Carry the source's comments (and, if asked, code) forward through line `line`, so
# they sit just ahead of the C for the statement on that line.
function annotate!(lines, sc::Scope, line)
    line > sc.cursor || return
    # A statement that runs on past `line` — brackets still open — is carried whole,
    # so its continuation lines come before its C, not after.
    sc.src !== nothing && (line = statementend(sc.src, line))
    if sc.src !== nothing
        for l in body(sc.src, sc.cursor + 1, line; code=sc.copycode)
            emit!(lines, sc, l)
        end
    end
    sc.cursor = line
end

# A blank line between the C of one Julia statement and the next, so that each
# statement — often several C lines — reads as a paragraph. None right after an
# opening brace; `cfunction` removes any left against a closing one.
separate!(lines, sc::Scope) = isempty(lines) || isempty(last(lines)) || endswith(last(lines), "{") || push!(lines, "")

# The type of a slot, shaped if it holds an array.
slottype(sc::Scope, i) = get(sc.slotshapes, i, widen(sc.ci.slottypes[i]))

# The declaration of a slot: by its type, or by the C struct of the tuple it holds.
slotdecl(sc::Scope, i) = haskey(sc.slotkinds, i) ? sc.slotkinds[i].cname * " " * sc.names[i] : declare(slottype(sc, i), sc.names[i])

# The layout of the tuple an IR value holds, if it is one of a known layout.
tuplekind(sc::Scope, x) = x isa Core.SSAValue ? get(sc.kinds, x.id, nothing) : x isa Core.SlotNumber ? get(sc.slotkinds, x.id, nothing) : nothing

# Emit the C for one IR statement, appending to `lines`.
function statement!(lines, sc::Scope, i, st)
    ci = sc.ci
    sc.current = i
    st === nothing && return
    if st isa GlobalRef                           # a global: resolved where it's used
        # A global with neither `const` nor a type is `Any` to Julia wherever it is read,
        # so nothing computed from it has a type. Refused by name, with the two ways to give it one.
        widen(ci.ssavaluetypes[i]) === Any && !Base.isconst(st.mod, st.name) &&
            throw(ArgumentError("`$(st.name)` is a global with neither `const` nor a type, so Julia has no type for it or for anything computed from it (line $(sc.stmtline[i])); write `const $(st.name) = …`, or `$(st.name)::$(typeof(getfield(st.mod, st.name))) = …` if it is to change"))
        # A global that isn't `const` is read here, and written where it is used, which is
        # later. If it can be given a new value in between, by a store or by a call that may
        # store, the value read is kept: `p, q = q, p` on two globals, `g + bump!()`.
        G = widen(ci.ssavaluetypes[i])
        if !Base.isconst(st.mod, st.name) && G <: Number && !(getfield(st.mod, st.name) isa AbstractIrrational)
            changes(k) = (c = consumer(ci.code[k]); c isa Expr && c.head === :call && (iscall(c, Core.setglobal!) || !pure(sc, c)))
            if any(u -> u > i && uses(ci.code[u], i) && any(changes, i+1:u-1), eachindex(ci.code))
                emit!(lines, sc, "$(ctype(G)) $(temp!(sc, i, contribution(sc, st))) = $(value(sc, st));")
            end
        end
        return
    end
    st isa Core.NewvarNode && return
    st isa Expr && st.head in (:meta, :code_coverage_effect) && return
    st isa Expr && st.head === :static_parameter && return      # the `T` of `where {T}`: a type, known when transpiled
    i in sc.inlined && return                     # rendered inside the expression that consumes it
    T = widen(ci.ssavaluetypes[i])
    throws(sc, i) && return throw!(lines, sc, consumer(st))
    # The value of a loop, which is `nothing`, kept in a variable of Julia's own making:
    # `@inbounds for …` lowers to that. No C.
    T === Nothing && (st isa Core.SlotNumber || st isa Expr && st.head === :(=) && st.args[2] === nothing) && return
    T === Union{} && return                       # unreachable
    if ci.ssavaluetypes[i] isa Core.Const && (ci.ssavaluetypes[i].val isa Char || ci.ssavaluetypes[i].val isa AbstractString)
        sc.expr[i] = value(sc, ci.ssavaluetypes[i].val)   # `Char(97)` is `'a'`; a string literal is itself
        return
    end
    if st isa Core.ReturnNode
        if valuetype(sc, st.val) === Nothing
            i == length(ci.code) || emit!(lines, sc, "return;")
            return
        end
        v = value(sc, st.val)
        if sc.resultparam
            # An array result is written into the out parameter; if it isn't there
            # already, copy it. The result has Julia's return type where that has a
            # size, otherwise the value's own; a transposed value landing in a plain
            # type is copied with its axes swapped. A `return` is only needed before
            # the end.
            shape(sc.rettype) === nothing && (sc.rettype = valuetype(sc, st.val))
            v == sc.resultname || outplacedwhole(sc, st.val) || copy!(lines, sc, v, valuetype(sc, st.val), sc.resultname, sc.rettype)
            i == length(ci.code) || emit!(lines, sc, "return;")
        else
            emitexpr!(lines, sc, "return ", v)
        end
    elseif st isa Expr && st.head === :foreigncall
        code = foreign!(sc, st)
        if T === Nothing
            emit!(lines, sc, code * ";")
        else
            name = onlyreturned(ci, i) ? result!(sc, i) : temp!(sc, i, parts(sc, foreignargs(sc, st)))
            emit!(lines, sc, "$(ctype(T)) $name = $code;")
        end
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) in (Base.print, Base.println)
        print!(lines, sc, st.args[2:end], callee(ci, st.args[1]) === Base.println)
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Printf.format && !(T <: AbstractString)
        printf!(lines, sc, st.args[2:end])
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) in (Base.fill!, Base.materialize!)
        inplace!(lines, sc, i, st)
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Core.setglobal! && length(st.args) == 4
        # `global count = …`, `global count += 1`: a store into the C global, which for that
        # is not `const`. It starts from the value it had when it was transpiled, as every global does.
        mod, name = literal(sc, st.args[2]), literal(sc, st.args[3])
        g = global!(sc.prog, mod, name, getfield(mod, name))
        G = globaltype(getfield(mod, name))
        G <: Number || throw(ArgumentError("assigning to the global `$name`, a $(G): only a scalar global can be given a new value; an array's elements can be written, `$name[i] = …` (statement $i)"))
        push!(sc.prog.written, (mod, name))
        text = first(expression(sc, st.args[4]))
        # `g += f(n)` leaves it to the compiler whether `g` is read before `f` runs, and `f`
        # may write `g`: shortened only when nothing on the right has an effect.
        effect(x) = x isa Core.SSAValue && (haskey(sc.alias, x.id) ? effect(sc.alias[x.id] isa Tuple ? sc.alias[x.id][2] : sc.alias[x.id]) : effect(ci.code[x.id])) ||
                    x isa Expr && (x.head === :call && !pure(sc, x) || any(effect, x.args))
        short = effect(st.args[4]) ? nothing : compound(g.cname, G, text)
        short === nothing ? emitexpr!(lines, sc, "$(g.cname) = ", text) : emit!(lines, sc, short * ";")
        sc.expr[i] = g.cname
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Base.sincos && length(st.args) == 2
        # `s, c = sincos(x)` is exactly `s = sin(x); c = cos(x)`: ISO C has no `sincos`,
        # and the compiler fuses the two calls itself. The pair is read by destructuring.
        a = expression(sc, st.args[2])[1]
        f = valuetype(sc, st.args[2]) === Float32 ? "f" : ""
        push!(sc.headers, "math.h")
        pair!(lines, sc, i, st.args[2:2], "sin$f($a)", "cos$f($a)")
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Base.minmax && length(st.args) == 3 &&
           valuetype(sc, st.args[2]) === valuetype(sc, st.args[3]) && valuetype(sc, st.args[2]) <: Union{Base.BitInteger64, Float32, Float64}
        # `lo, hi = minmax(a, b)` is `lo = min(a, b); hi = max(a, b)`, read the same way.
        A = valuetype(sc, st.args[2])
        a, b = expression(sc, st.args[2])[1], expression(sc, st.args[3])[1]
        A <: AbstractFloat && push!(sc.headers, "math.h")
        A <: AbstractFloat ? pair!(lines, sc, i, st.args[2:3], "$(mathname(A, "fmin"))($a, $b)", "$(mathname(A, "fmax"))($a, $b)") :
                             pair!(lines, sc, i, st.args[2:3], "($a < $b ? $a : $b)", "($a > $b ? $a : $b)")
    elseif st isa Expr && st.head === :call && (T === Nothing || T === Any) && userinstance!(sc, callee_or_nothing(ci, st.args[1]), st.args[2:end]) !== nothing
        # A call for its effect, or whose result goes unused (Julia then types it `Any`
        # and the callee's own return type says what C needs).
        mi, _, name = userinstance!(sc, callee(ci, st.args[1]), st.args[2:end])
        R = returntype(mi)
        if isarray(R)
            t = temp!(sc, i, callparts(sc, st))
            emit!(lines, sc, declare(R, t) * ";")
            emit!(lines, sc, "$name($(callargs(sc, st.args[2:end])), $t);")
        else
            emit!(lines, sc, "$name($(callargs(sc, st.args[2:end])));")
        end
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Core.tuple && sc.kind !== nothing &&
           (onlyreturned(ci, i) || storedforreturn(sc, i)) && !any(a -> isarray(valuetype(sc, a)), st.args[2:end])
        # `return x, ẋ` — or `t = (x, ẋ); return t` — : the function's own struct, as a literal.
        sc.expr[i] = "($(sc.kind.cname)){$(join((value(sc, a) for a in st.args[2:end]), ", "))}"
        sc.kinds[i] = sc.kind
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Core.tuple && consumedbycalls(sc, i)
        # A tuple built only to be passed to the user's functions: its elements go
        # separately, so it never exists in C.
        sc.kinds[i] = Kind("", [value(sc, a) for a in st.args[2:end]])
    elseif st isa Expr && st.head === :call && (callee_or_nothing(ci, st.args[1]) === Core.tuple || (callee_or_nothing(ci, st.args[1]) isa Type && isstruct(T)))
        # A tuple or struct value: `(Point){x, y}`, or field by field when a field is an array.
        if callee_or_nothing(ci, st.args[1]) === Core.tuple && sc.kind !== nothing && onlyreturned(ci, i)
            # A returned tuple with an array in it: the function's struct, field by field. A
            # field computed into its place (`placement`) is there already.
            haskey(sc.placed, i) || emit!(lines, sc, "$(sc.kind.cname) result;")
            for (F, c, a) in zip(T.parameters, sc.kind.fields, st.args[2:end])
                value(sc, a) == "result.$c" && continue
                isarray(F) ? copy!(lines, sc, value(sc, a), valuetype(sc, a), "result.$c", F) : emit!(lines, sc, "result.$c = $(value(sc, a));")
            end
            sc.expr[i] = "result"
            sc.kinds[i] = sc.kind
            return
        end
        if isstruct(T) && onlyreturned(ci, i) && !any(a -> isarray(valuetype(sc, a)), st.args[2:end])
            # `return Point(x, y)`: the literal in the `return`.
            structdef!(sc.prog, T)
            sc.expr[i] = compound(sc, T, st.args[2:end])
            return
        end
        placed = haskey(sc.placed, i)
        dest = placed ? sc.placed[i] : onlyreturned(ci, i) ? result!(sc, i) : temp!(sc, i, parts(sc, st))
        compound!(lines, sc, i, T, st.args[2:end], dest; declared=placed)
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) === Base.indexed_iterate
        # `x, y = t`: the k-th field, as the value; the iterator state is compile-time.
        t, k = st.args[2], st.args[3]
        sc.expr[i] = fieldaccess(sc, t, k)
        isarray(T) && (sc.shapes[i] = widen(ci.ssavaluetypes[i]).parameters[1])
    elseif st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) in (Base.getproperty, Core.getfield, Base.getindex) && !isarray(valuetype(sc, st.args[2])) && (isstruct(valuetype(sc, st.args[2])) || istuple(valuetype(sc, st.args[2])) || isindexediterate(sc, st.args[2]))
        # A field read is just a name: no temp.
        sc.expr[i] = isindexediterate(sc, st.args[2]) ? value(sc, st.args[2]) : fieldaccess(sc, st.args[2], st.args[3])
        isarray(T) && (sc.shapes[i] = T)
    elseif st isa Expr && st.head === :call
        f = callee_or_nothing(ci, st.args[1])
        if f === Base.setproperty! || f === Base.setfield!
            S = valuetype(sc, st.args[2])
            F = fieldtype(S, literal(sc, st.args[3]))
            target = fieldaccess(sc, st.args[2], st.args[3])
            isarray(F) ? copy!(lines, sc, value(sc, st.args[4]), valuetype(sc, st.args[4]), target, F) :
                         emit!(lines, sc, "$target = $(value(sc, st.args[4]));")
        elseif f === Base.setindex! && any(k -> literal(sc, k) isa Colon || literal(sc, k) isa AbstractUnitRange || isarray(valuetype(sc, k)), st.args[4:end])
            setslice!(lines, sc, i, st.args[2], st.args[3], st.args[4:end])
        elseif f === Base.setindex!
            emit!(lines, sc, "$(index(sc, st.args[2], st.args[4:end])) = $(value(sc, st.args[3]));")
        elseif f === Base.vect && literal(sc, Core.SSAValue(i)) isa AbstractVector && onlyindexes(sc, i)
            # `[1, 3]` written as an index, `A[2:end, [1, 3]]`: compile-time, like a literal range.
            return
        elseif f in (Base.zeros, Base.ones, Base.fill) || (f in (Base.zero, Base.one) && isarray(T)) || isconstruction(f) || f === Base.materialize
            dest = onlyreturned(ci, i) ? result!(sc, i) : temp!(sc, i, parts(sc, st))
            construct!(lines, sc, i, st, dest; declaration=!(onlyreturned(ci, i) && sc.resultparam))
        elseif (f === Base.adjoint || f === Base.transpose) && isarray(T)
            # A transpose is the same storage with its axes read the other way round:
            # nothing to do in C, the value just carries the tag from here on. A
            # transpose of an adjoint, or the reverse, is a conjugate without a
            # transpose, which no tag says: that one is made, `conj.(A)` into a temp.
            S = valuetype(sc, st.args[2])
            if istransposed(S) && isconjugated(S) != (f === Base.adjoint && eltype(S) <: Complex)
                returned = onlyreturned(ci, i) && sc.resultparam
                conjugate!(lines, sc, value(sc, st.args[2]), S, returned ? result!(sc, i) : temp!(sc, i, callparts(sc, st)); declaration=!returned)
                sc.shapes[i] = plain(S)
            else
                sc.expr[i] = value(sc, st.args[2])
                sc.shapes[i] = transposed(S; conj=f === Base.adjoint)
            end
        elseif f in (Base.lastindex, Base.firstindex, Base.length, Base.size) && (v = literal(sc, Core.SSAValue(i))) isa Integer
            # A size the transpiler knows — inference's, for a static array, or its own,
            # for a regular array it built or was given a size for: the number, no temp.
            sc.expr[i] = string(v)
        elseif f === Colon() || f === Base.OneTo || f === Base.eachindex || f === Base.axes
            # A literal range that only indexes (`v[2:end]`) is compile-time; any other
            # range outside a `for` has no C.
            literal(sc, Core.SSAValue(i)) isa AbstractRange && onlyindexes(sc, i) && return
            throw(ArgumentError("ranges are only supported as the range of a for loop (statement $i)"))
        elseif isarray(T) && foldable(sc, i, st)
            # `-x` feeding `x * s` or `x / s`: the sign goes onto the scalar, exactly.
            push!(sc.negated, i)
            sc.expr[i] = value(sc, st.args[2])
            sc.shapes[i] = valuetype(sc, st.args[2])
        elseif isarray(T)
            # A calculation whose only use is to be returned is the function's result.
            if onlyreturned(ci, i)
                dest = result!(sc, i)
                arraycall!(lines, sc, i, st, dest; declaration=!sc.resultparam)
            elseif (p = placement(sc, i)) !== nothing
                # Its one use is a field of a struct or tuple being built: computed straight
                # into that field, `mul_s_3(s, axis, q.v)`, the struct declared here.
                u, name, decl, field = p
                decl === nothing || emit!(lines, sc, decl * ";")
                sc.placed[u] = name
                arraycall!(lines, sc, i, st, "$name.$field"; declaration=false)
                sc.expr[i] = "$name.$field"
            else
                arraycall!(lines, sc, i, st, temp!(sc, i, callparts(sc, st)); declaration=true)
            end
        elseif compiletime(ci.ssavaluetypes[i])
            return                                # a type or Val: no C meaning
        elseif istuple(T) && (r = userinstance!(sc, callee_or_nothing(ci, st.args[1]), st.args[2:end])) !== nothing
            # A call to a user function that returns a tuple: its struct, named after it.
            # Returned straight on, the callee's struct is this function's too.
            mi, _, cname = r
            k = returnkind!(sc.prog, mi, cname)
            sc.kinds[i] = k
            code = "$cname($(callargs(sc, st.args[2:end])))"
            if onlyreturned(ci, i)
                sc.expr[i] = code
            else
                name = temp!(sc, i, callparts(sc, st))
                emit!(lines, sc, "$(k.cname) $name = $code;")
            end
        else
            code, _ = render(sc, i, st)
            name = onlyreturned(ci, i) ? result!(sc, i) : temp!(sc, i, callparts(sc, st))
            emitexpr!(lines, sc, "$(ctype(T)) $name = ", code)
            haskey(sc.math, i) && step!(lines, sc, "$name = $(sc.math[i])")
        end
    elseif st isa Expr && st.head === :(=)
        # `%i = (x = rhs)`: the SSA value is the value assigned. Refer to it as `x`
        # where that's safe; otherwise keep a temp copy.
        slot, rhs = st.args
        if slot.id in sc.hidden && !any(F -> F.var == slot.id, values(sc.fors))
            # A slot Julia left unnamed that really holds a value — the result of a
            # `c ? x : y` used as a value — is a local like any other, named as a temp.
            # Not a loop's own variable, which is hidden only because its loop declares
            # it: assigned in the body, it is assigned under its own name (`forloop!`).
            delete!(sc.hidden, slot.id)
            sc.names[slot.id] = temp!(sc, nothing, String[])
        end
        x = sc.names[slot.id]
        # A variable is declared at its first assignment. Inside an `if` or a loop that
        # would scope it to the block, so there it is declared just before the construct.
        # A variable is declared in its home block (`homes`): here, when this is that block;
        # otherwise just above the construct, in that block, that this statement is inside.
        fresh = !(slot.id in sc.declared) && !(slot.id in sc.hidden)
        fresh && push!(sc.declared, slot.id)
        home = get(sc.home, slot.id, 1)
        here = fresh && sc.path[end] == home
        if isarray(T)
            store!(lines, sc, i, x, rhs; declaration=here)
        elseif rhs isa Expr && rhs.head === :call && callee_or_nothing(ci, rhs.args[1]) === Core.tuple && sc.kind !== nothing &&
               returnedslot(ci) == slot.id && !any(a -> isarray(valuetype(sc, a)), rhs.args[2:end])
            # `t = (x, ẋ)` in the variable the function returns: the function's own struct.
            emit!(lines, sc, "$(here ? sc.kind.cname * " " : "")$x = ($(sc.kind.cname)){$(join((value(sc, a) for a in rhs.args[2:end]), ", "))};")
            sc.slotkinds[slot.id] = sc.kind
        elseif rhs isa Expr && rhs.head === :call && (callee_or_nothing(ci, rhs.args[1]) === Core.tuple || (callee_or_nothing(ci, rhs.args[1]) isa Type && isstruct(T)))
            compound!(lines, sc, i, T, rhs.args[2:end], x; declared=!here || haskey(sc.placed, i))
        else
            text = rhs isa Expr ? first(render(sc, i, rhs)) : value(sc, rhs)
            short = here ? nothing : compound(x, T, text)
            k = tuplekind(sc, rhs)
            if k === nothing && istuple(T) && rhs isa Expr && rhs.head === :call &&
               (r = userinstance!(sc, callee_or_nothing(ci, rhs.args[1]), rhs.args[2:end])) !== nothing
                k = returnkind!(sc.prog, r[1], r[3])   # `t = step(…)`: the callee's struct
            end
            k === nothing || isempty(k.cname) || (sc.slotkinds[slot.id] = k)
            # Declared with the variable's type, which may be wider than this value's
            # (`onetype!`); an integer literal going into a float variable is spelled as one.
            D = slottype(sc, slot.id)
            D <: AbstractFloat && rhs isa Integer && (text = value(sc, D(rhs)))
            short === nothing ? emitexpr!(lines, sc, (here ? (k === nothing || isempty(k.cname) ? ctype(D) : k.cname) * " " : "") * "$x = ", text) : emit!(lines, sc, short * ";")
        end
        if fresh && !here
            s = slot.id
            d = sc.blocks[home].depth
            push!(sc.inserts, (sc.starts[d+1], 0, () -> "    "^d * slotdecl(sc, s) * ";"))
            # It is written later, but it names its type — `Gain q;` — and that is a mention
            # like any other, for a local spelled like the struct to keep clear of.
            push!(sc.emitted, (sc.path[end], try slotdecl(sc, s) catch; "" end))
        end
        if stable(ci, i, slot.id)
            sc.expr[i] = x
            # The value just stored is now also `x`; if it was a temp, later uses
            # (typically the return) can say `x` instead.
            rhs isa Core.SSAValue && !(rhs.id in sc.inlined) && (sc.expr[rhs.id] = x)
        else
            t = temp!(sc, i, contribution(sc, slot))
            emit!(lines, sc, isarray(T) ? "$(declare(valuetype(sc, slot), t));" : "$(ctype(T)) $t = $x;")
            isarray(T) && copy!(lines, sc, x, valuetype(sc, slot), t, valuetype(sc, slot))
        end
        isarray(T) && (sc.shapes[i] = valuetype(sc, slot))
    elseif haskey(sc.choices, i)
        # `a && b`, `c ? x : y`, used where it can't be written in place: one line, into a temp.
        emitexpr!(lines, sc, "$(ctype(T)) $(temp!(sc, i, String[])) = ", first(chosen(sc, sc.choices[i])))
    elseif st isa Core.SlotNumber
        # `%i = x`: a read of a variable. Same rule as above.
        x = sc.names[st.id]
        haskey(sc.slotkinds, st.id) && (sc.kinds[i] = sc.slotkinds[st.id])
        # The variable's type carries the shape the transpiler knows; the statement's
        # may not, for a regular array (`Matrix{Float64}`).
        V = valuetype(sc, st)
        if stable(ci, i, st.id)
            sc.expr[i] = x
        else
            t = temp!(sc, i, contribution(sc, st))
            emit!(lines, sc, isarray(V) ? "$(declare(V, t));" : "$(ctype(T)) $t = $x;")
            isarray(V) && copy!(lines, sc, x, V, t, V)
        end
        isarray(V) && (sc.shapes[i] = V)
    elseif st isa Core.SSAValue || st isa Number
        sc.expr[i] = value(sc, st)                 # pure copy; no temp needed
        isarray(T) && (sc.shapes[i] = valuetype(sc, st))
    elseif st isa Core.GotoIfNot || st isa Core.GotoNode
        throw(ArgumentError("control flow not recognised at statement $i"))
    else
        throw(ArgumentError("unsupported statement: $st"))
    end
end

# The two values of `sincos(x)` or `minmax(a, b)` are written where each is read, which is
# after this statement. If a variable they are computed from is given a new value later on,
# `a, b = minmax(a, b)`, the second would read the first's result: then both are computed
# here, into temps.
function pair!(lines, sc::Scope, i, args, first, second)
    code = sc.ci.code
    slots, changeable = Set{Int}(), Ref(false)
    function read!(x)               # what it is computed from, through whatever is written inside it
        x isa Core.SlotNumber && return push!(slots, x.id)
        x isa GlobalRef && !Base.isconst(x.mod, x.name) && (changeable[] = true)      # a global: anything may store into it
        x isa Core.SSAValue && return read!(code[x.id])
        x isa Expr && foreach(read!, x.head === :(=) ? x.args[2:end] : x.args)
    end
    foreach(read!, args)
    if changeable[] || any(k -> any(s -> assigns(code[k], s), slots), i+1:length(code))
        E = ctype(widen(sc.ci.ssavaluetypes[i]).parameters[1])
        names = (temp!(sc, nothing, String[]), temp!(sc, nothing, String[]))
        emit!(lines, sc, "$E $(names[1]) = $first;")
        emit!(lines, sc, "$E $(names[2]) = $second;")
        first, second = names
    end
    sc.pair[i] = (first, second)
end

# A statement whose value is a type, a `Val`, or a tuple: compile-time only.
compiletime(t) = t isa Core.Const && !(t.val isa Number) && !(t.val isa AbstractArray) && !(t.val isa Char) && !(t.val isa AbstractString)

# Emit `x = rhs` for an array `x`: a helper writing straight into `x` when `x` isn't
# also an operand, otherwise through a temp so the operation can't read what it's
# overwriting.
function store!(lines, sc::Scope, i, x, rhs; declaration::Bool=false)
    slot = sc.ci.code[i].args[1].id
    # With `declaration`, `x` is declared here, at its first assignment: by the emitter
    # that writes it when there is one, otherwise just before the copy into it.
    if rhs isa Expr
        f = callee_or_nothing(sc.ci, rhs.args[1])
        making = f in (Base.zeros, Base.ones, Base.fill, Base.zero, Base.one) || isconstruction(f) || f === Base.materialize
        if f in (Core.getfield, Base.getproperty, Base.getindex) && (isindexediterate(sc, rhs.args[2]) || isstruct(valuetype(sc, rhs.args[2])) || istuple(valuetype(sc, rhs.args[2])))
            # An array field of a struct or tuple, copied out: `copy_3(t.a, p);`.
            T = slottype(sc, slot)
            src = isindexediterate(sc, rhs.args[2]) ? value(sc, rhs.args[2]) : fieldaccess(sc, rhs.args[2], rhs.args[3])
            declaration && emit!(lines, sc, declare(T, x) * ";")
            copy!(lines, sc, src, T, x, T)
            sc.shapes[i] = T
        elseif (f === Base.adjoint || f === Base.transpose) && isarray(valuetype(sc, rhs.args[2]))
            # `B = A'`: a copy into whatever Julia says `B` is. A lazy `Adjoint` (a
            # vector's) is the same storage, known to be transposed; an eager one
            # (StaticArrays materializes a matrix transpose) is copied axes-swapped.
            S = valuetype(sc, rhs.args[2])
            if istransposed(S) && isconjugated(S) != (callee_or_nothing(sc.ci, rhs.args[1]) === Base.adjoint && eltype(S) <: Complex)
                conjugate!(lines, sc, value(sc, rhs.args[2]), S, x; declaration)   # `B = transpose(A')`: conj.(A)
                sc.shapes[i] = plain(S)
            else
                A = transposed(S; conj=callee_or_nothing(sc.ci, rhs.args[1]) === Base.adjoint)
                R = slottype(sc, slot)
                shape(R) === nothing && (R = A)
                declaration && emit!(lines, sc, declare(R, x) * ";")
                start = length(lines) + 1
                if mentions(sc, x, rhs.args[2]) && axis(A) != axis(R)
                    # `a = a'`: the copy swaps axes, and onto its own storage it would read
                    # elements it has already written. Through a temp, like any operation
                    # that reads what it writes.
                    t = temp!(sc, nothing, contribution(sc, rhs.args[2]))
                    emit!(lines, sc, declare(R, t) * ";")
                    copy!(lines, sc, value(sc, rhs.args[2]), A, t, R)
                    copy!(lines, sc, t, R, x, R)
                else
                    copy!(lines, sc, value(sc, rhs.args[2]), A, x, R)
                end
                step!(lines, sc, "$x = $(value(sc, rhs.args[2]))$(tmark(A))"; from=start)
                sc.shapes[i] = R
            end
        elseif any(a -> mentions(sc, x, a), rhs.args[2:end]) && !inplace(sc, rhs, slottype(sc, slot))
            # `x` is also an operand of something that reads elements it has already
            # written — a product, a solve, a transpose, a construction: through a temp.
            t = temp!(sc, nothing, parts(sc, rhs))
            making ? construct!(lines, sc, i, rhs, t; declaration=true) : arraycall!(lines, sc, i, rhs, t; declaration=true)
            declaration && emit!(lines, sc, declare(valuetype(sc, Core.SSAValue(i)), x) * ";")
            copy!(lines, sc, t, valuetype(sc, Core.SSAValue(i)), x, valuetype(sc, Core.SSAValue(i)))
        elseif making
            construct!(lines, sc, i, rhs, x; declaration)
        else
            arraycall!(lines, sc, i, rhs, x; declaration)
        end
        slotshape!(sc, slot, sc.shapes[i])
    else
        # `m = v` on a mutable array makes `m` another name for the same array in Julia, and
        # a copy here: harmless while neither is written, and a wrong answer once one is
        # (writes through `m` never reached `v`, or the caller). Refused until the C can
        # hold one array under two names.
        other = slotof(sc, rhs)
        T = sc.ci.slottypes[slot]
        if other !== nothing && other != slot && T isa Type && ismutabletype(widen(T)) && (slot in sc.mutated || other in sc.mutated)
            throw(ArgumentError("`$(sc.ci.slotnames[slot]) = $(sc.ci.slotnames[other])` gives one mutable array a second name in Julia, so a write through either changes both; in C `$(sc.ci.slotnames[slot])` would be a copy, and the write would be lost (line $(sc.stmtline[sc.current])). Write through `$(sc.ci.slotnames[other])` itself, or say `copy($(sc.ci.slotnames[other]))` if a copy is what is meant"))
        end
        declaration && emit!(lines, sc, declare(valuetype(sc, rhs), x) * ";")
        copy!(lines, sc, value(sc, rhs), valuetype(sc, rhs), x, valuetype(sc, rhs))
        slotshape!(sc, slot, valuetype(sc, rhs))
    end
end

# A variable is one C array, of the size its first value had. A regular array
# reassigned at another size — `a = [1.0; 2.0]` then `a = [1.0; 2.0; 3.0]`, one Julia
# type — is refused by name and line; a static one is two types, refused by `onetype!`.
function slotshape!(sc::Scope, slot, T)
    old = get(sc.slotshapes, slot, nothing)
    if old !== nothing && shape(old) !== nothing && shape(T) !== nothing && collect(shape(old)) != collect(shape(T))
        throw(ArgumentError("`$(sc.ci.slotnames[slot])` is a $(describe(old)) and then a $(describe(T)) at line $(sc.stmtline[sc.current]); C holds it as one array of one size, so use a name for each"))
    end
    sc.slotshapes[slot] = T
end

# Calls that make a whole array: `zeros`/`ones`/`fill`, `zero`/`one`, `SMatrix{…}(I)`,
# block construction and array literals, static constructors, and a broadcast being
# materialized.
function construct!(lines, sc::Scope, i, ex::Expr, dest; declaration::Bool=false)
    f = callee(sc.ci, ex.args[1])
    args = ex.args[2:end]
    f === Base.materialize && return broadcast!(lines, sc, i, args[1], dest; declaration)
    T = widen(sc.ci.ssavaluetypes[i])
    if isconstruction(f) && length(args) == 1 && literal(sc, args[1]) isa LinearAlgebra.UniformScaling
        # `SMatrix{3,3}(I)`, `SMatrix{3,3}(2I)`: the identity matrix, or a multiple of it.
        λ = literal(sc, args[1]).λ
        declaration && emit!(lines, sc, declare(T, dest) * ";")
        start = length(lines) + 1
        identity!(lines, sc, dest, T; diagonal=λ == 1 ? nothing : value(sc, eltype(T)(λ)))
        step!(lines, sc, "$dest = $(λ == 1 ? "" : value(sc, λ))I"; from=start)
        sc.shapes[i] = T
        return
    end
    isconstruction(f) && return concatenate!(lines, sc, i, f, args, dest; declaration)
    if f in (Base.zero, Base.one) || (f in (Base.zeros, Base.ones) && length(args) == 1 && literal(sc, args[1]) isa Type) ||
       (f === Base.fill && length(args) == 2 && literal(sc, args[2]) isa Type)
        # `zero(A)`, `zeros(SMatrix{3,4})`, `one(A)`, `fill(x, SMatrix{2,2})`: the size is in
        # the result's type.
        shape(T) === nothing && throw(ArgumentError("$f needs a static array type (statement $i)"))
        declaration && emit!(lines, sc, declare(T, dest) * ";")
        x = f === Base.fill ? value(sc, args[1]) : eltype(T) <: AbstractFloat ? "1.0" : "1"
        start = length(lines) + 1
        f === Base.one ? identity!(lines, sc, dest, T) :
        f in (Base.zero, Base.zeros) ? zero!(lines, sc, dest, T) :
        fill!(lines, sc, dest, T, x)
        step!(lines, sc, f === Base.one ? "$dest = I" : f in (Base.zero, Base.zeros) ? "$dest .= 0" : "$dest .= $x"; from=start)
        sc.shapes[i] = T
        return
    end
    x = f === Base.fill ? value(sc, args[1]) : "1.0"
    f === Base.fill && (args = args[2:end])
    dims = [literal(sc, a) isa Integer ? literal(sc, a) : throw(ArgumentError("$f needs literal dimensions (statement $i)")) for a in args]
    R = shaped(eltype(T), Tuple(dims))
    eltype(T) <: AbstractFloat || f !== Base.ones || (x = "1")
    declaration && emit!(lines, sc, declare(R, dest) * ";")
    start = length(lines) + 1
    f === Base.zeros ? zero!(lines, sc, dest, R) : fill!(lines, sc, dest, R, x)
    step!(lines, sc, f === Base.zeros ? "$dest .= 0" : "$dest .= $x"; from=start)
    sc.shapes[i] = R
end

# The compile-time value of `x`, or `nothing` if it has none.
function literal(sc::Scope, x)
    x isa QuoteNode && return x.value
    x isa GlobalRef && return getfield(x.mod, x.name)
    x isa Core.SSAValue || return x
    t = sc.ci.ssavaluetypes[x.id]
    t isa Core.Const && return t.val
    haskey(sc.known, x.id) && return sc.known[x.id]
    # What Julia didn't fold but the transpiler can: a size of an array whose shape it
    # knows (`end` on a regular array it built), and a range with such ends.
    st = sc.ci.code[x.id]
    st isa Expr && st.head === :call || return nothing
    f = callee_or_nothing(sc.ci, st.args[1])
    v = nothing
    if f in (Base.lastindex, Base.firstindex, Base.length, Base.size)
        v = sizeknown(sc, x.id, f, st.args[2:end])
    elseif f in (Base.:+, Base.:-, Base.:*, Base.div) && length(st.args) == 3
        # Arithmetic on sizes the transpiler knows, as an index has it: `1:end-1`, `end ÷ 2`.
        a, b = literal(sc, st.args[2]), literal(sc, st.args[3])
        a isa Integer && b isa Integer && (v = f(a, b))
    elseif f === Colon() && length(st.args) in (3, 4)
        ends = [literal(sc, a) for a in st.args[2:end]]
        all(e -> e isa Integer, ends) && (v = length(ends) == 2 ? (ends[1]:ends[2]) : (ends[1]:ends[2]:ends[3]))
    elseif f === Base.vect && length(st.args) > 1
        items = [literal(sc, a) for a in st.args[2:end]]   # `[1, 3]` written out, as an index
        all(e -> e isa Integer, items) && (v = Int[items...])
    end
    v === nothing || (sc.known[x.id] = v)
    return v
end

# The integer `lastindex(A[, d])`, `firstindex`, `length(A)` or `size(A, d)` yields when
# the array's size is known — by inference, or by the transpiler for a regular array
# it built or was given a size for — else nothing.
function sizeknown(sc::Scope, i, f, args)
    t = sc.ci.ssavaluetypes[i]
    t isa Core.Const && t.val isa Integer && return t.val
    isempty(args) && return nothing
    T = valuetype(sc, args[1])
    isarray(T) && shape(T) !== nothing || return nothing
    s = shape(T)
    d = length(args) == 2 ? literal(sc, args[2]) : nothing
    length(args) == 2 && !(d isa Integer && 1 <= d <= length(s)) && return nothing
    f === Base.firstindex && return 1
    f === Base.length && return prod(s)
    f === Base.lastindex && return d === nothing ? prod(s) : s[d]
    f === Base.size && return d === nothing ? nothing : s[d]
    return nothing
end

# `hvcat`, `vcat`, `hcat`, `vect`, their `typed_` forms, and static-array constructors.
isconstruction(f) = f in (Base.hvcat, Base.vcat, Base.hcat, Base.vect, Base.typed_hvcat, Base.typed_vcat, Base.typed_hcat, Base.hvncat) ||
                    (f isa Type && f <: StaticArrays.StaticArray)

# Block construction and array literals. An all-scalar literal is declared with its
# initializer, or assigned element by element where it can't be; anything with an array
# block is moved into place block by block.
function concatenate!(lines, sc::Scope, i, f, args, dest; declaration::Bool=false)
    ci = sc.ci
    tupleof(x) = x isa Core.SSAValue && iscall(ci.code[x.id], Core.tuple) ? ci.code[x.id].args[2:end] :
                 x isa Core.SSAValue && ci.ssavaluetypes[x.id] isa Core.Const ? collect(ci.ssavaluetypes[x.id].val) : nothing
    if f isa Type
        # `SVector(a, b, c)`, `SMatrix{2,2}(t)`: elements in column-major order.
        R = widen(ci.ssavaluetypes[i])
        if length(args) == 1 && literal(sc, args[1]) === undef
            # `MVector{3,Float64}(undef)`: room and nothing in it, which in C is the declaration.
            declaration && emit!(lines, sc, declare(R, dest) * ";")
            sc.shapes[i] = R
            return
        end
        elems = length(args) == 1 && tupleof(args[1]) !== nothing ? tupleof(args[1]) : args
        all(a -> !isarray(valuetype(sc, a)), elems) || throw(ArgumentError("a static constructor from arrays is not supported (statement $i)"))
        s = shape(R)
        if declaration
            # Declared here: with its initializer, in one go, as the Julia was written.
            grid = Array{String}(undef, s...)
            for k in eachindex(elems); grid[k] = value(sc, elems[k]); end   # column-major, as they arrive
            initialize!(lines, sc, declare(R, dest), grid)
        else
            # Elements arrive column-major; write them row by row, as a person would.
            order = length(s) == 1 ? eachindex(elems) : sort(eachindex(elems); by=k -> ((k - 1) % s[1], (k - 1) ÷ s[1]))
            for k in order
                sub = length(s) == 1 ? "[$(k-1)]" : "[$((k-1) % s[1])][$((k-1) ÷ s[1])]"
                emit!(lines, sc, "$dest$sub = $(value(sc, elems[k]));")
            end
        end
        sc.shapes[i] = R
        return
    end
    f in (Base.typed_hvcat, Base.typed_vcat, Base.typed_hcat) && (args = args[2:end])
    # Every form is a tree of concatenations (see `layout` in move.jl).
    if f in (Base.hvcat, Base.typed_hvcat)
        rows = tupleof(args[1])
        rows === nothing && throw(ArgumentError("hvcat needs literal row lengths (statement $i)"))
        blocks = args[2:end]
        starts = cumsum([1; rows[1:end-1]])
        tree = (1, Any[(2, Any[k:k+n-1...]) for (k, n) in zip(starts, rows)])
    elseif f === Base.hvncat && literal(sc, args[1]) isa Tuple
        blocks = args[3:end]
        tree = grouped(literal(sc, args[1]), literal(sc, args[2]) === true, 1:length(blocks))
    elseif f === Base.hvncat
        d = literal(sc, args[1])
        d isa Integer && d >= 1 || throw(ArgumentError("concatenation needs a literal dimension (statement $i)"))
        blocks = args[2:end]
        tree = (d, Any[1:length(blocks)...])
    else
        blocks = args
        tree = (f in (Base.vcat, Base.typed_vcat, Base.vect) ? 1 : 2, Any[1:length(blocks)...])
    end
    types = [valuetype(sc, b) for b in blocks]
    size, _ = layout(tree, types)
    T = widen(ci.ssavaluetypes[i])
    E = eltype(T)
    R = shape(T) !== nothing ? T : shaped(E, Tuple(ndims(T) == 1 ? size[1:1] : size))
    ndims(R) == 1 && any(!=(1), size[2:end]) && throw(ArgumentError("a vector can't hold $(join(size, "×")) (statement $i)"))
    if declaration && all(T -> !isarray(T), types)
        # An all-scalar literal declared here: with its initializer, a line per row, in
        # one go, as the Julia was written. Elsewhere — into `out`, or a reassignment —
        # element by element.
        _, places = layout(tree, types)
        grid = Array{String}(undef, shape(R)...)
        for (b, off) in places
            grid[([off; zeros(Int, ndims(R))][1:ndims(R)] .+ 1)...] = value(sc, blocks[b])
        end
        start = length(lines) + 1
        initialize!(lines, sc, declare(R, dest), grid)
        step!(lines, sc, "$dest = $(catnotation(sc, tree, blocks, f))"; from=start)
        sc.shapes[i] = R
        return
    end
    declaration && emit!(lines, sc, declare(R, dest) * ";")
    start = length(lines) + 1
    construct!(lines, sc, tree, blocks, dest, R)
    step!(lines, sc, "$dest = $(catnotation(sc, tree, blocks, f))"; from=start)
    sc.shapes[i] = R
end

# A block construction in Julia's bracket notation, with the C names: `[A B; C D]` for
# the `hvcat` family, the `;;` form for `hvncat`.
function catnotation(sc::Scope, tree, blocks, f)
    hv = f === Base.hvncat
    text(node) = node isa Integer ? spell(valuetype(sc, blocks[node]), value(sc, blocks[node])) :
                 join((text(c) for c in node[2]), hv ? ";"^node[1] * " " : node[1] == 1 ? "; " : " ")
    return "[" * text(tree) * "]"
end

# A broadcast tree, from its `broadcasted` root, into `dest`. Julia fuses nested
# broadcasts into one loop; here each level is its own helper, chained through temps.
function broadcast!(lines, sc::Scope, i, root, dest; declaration::Bool=false)
    ci = sc.ci
    node = ci.code[root.id]                       # broadcasted(f, args...)
    f = callee(ci, node.args[2])
    args = node.args[3:end]
    # `x .^ 2`: a literal exponent is part of the operation, not an operand.
    power = nothing
    if f === Base.literal_pow
        p = literal(sc, args[3])
        p isa Val || throw(ArgumentError("unsupported broadcast power (statement $i)"))
        power = typeof(p).parameters[1]
        args = [args[2]]
    end
    # Inner broadcasts first, each into a temp.
    inputs = Any[]
    for a in args
        if a isa Core.SSAValue && iscall(ci.code[a.id], Base.broadcasted)
            t = temp!(sc, a.id, parts(sc, ci.code[a.id]))
            broadcast!(lines, sc, a.id, a, t; declaration=true)
            push!(inputs, Core.SSAValue(a.id))
        else
            push!(inputs, a)
        end
    end
    types = [valuetype(sc, a) for a in inputs]
    any(isarray, types) || throw(ArgumentError("a broadcast over scalars only (statement $i)"))
    bs = broadcastshape(types)
    bs === nothing && throw(ArgumentError("broadcast: shapes don't line up: $(join(dims.(filter(isarray, types)), ", "))"))
    T = widen(ci.ssavaluetypes[i])
    if isarray(T)
        E = eltype(T)
        R = shape(T) !== nothing ? T :
            T <: LinearAlgebra.Adjoint || T <: LinearAlgebra.Transpose ? Transposed{E, Tuple(reverse(bs)[1:ndims(T)]), ndims(T)} : shaped(E, bs)
    else
        # An inner node of a fused broadcast: the IR only knows it as a `Broadcasted`.
        E = promote_type((isarray(t) ? eltype(t) : t for t in types)...)
        R = all(t -> !isarray(t) || istransposed(t), types) ?
            (nd = maximum(ndims(t) for t in types if isarray(t)); Transposed{E, Tuple(reverse(bs)[1:nd]), nd}) : shaped(E, bs)
    end
    op, cfn = power === nothing ? broadcastop(f, length(inputs), E) : (Symbol("pow", power < 0 ? "m" : "", abs(power)), power)
    cfn isa String && push!(sc.headers, cfn == "llabs" ? "stdlib.h" : "math.h")
    Ein = promote_type((isarray(t) ? eltype(t) : t for t in types)...)   # the elements the function is applied to
    cfn isa String && cfn in ("real", "imag", "conj", "angle") && !(Ein <: Complex) && throw(ArgumentError("$cfn broadcast over real elements is not supported (statement $i)"))
    cfn isa String && cfn != "llabs" && (cfn = mathname(Ein, cfn))        # the `f` family, the `c` family
    declaration && emit!(lines, sc, declare(R, dest) * ";")
    name = broadcasthelper!(sc.helpers, op, cfn, types, R)
    emit!(lines, sc, "$name($(join((value(sc, a) for a in inputs), ", ")), $dest);")
    spelled = [spell(valuetype(sc, a), value(sc, a)) for a in inputs]
    step!(lines, sc, "$dest = " * (power !== nothing ? "$(spelled[1]) .^ $power" :
                                    length(inputs) == 1 ? (cfn == :neg ? ".-$(spelled[1])" : cfn == :not ? ".!$(spelled[1])" : "$op.($(spelled[1]))") :
                                    length(inputs) == 2 && haskey(dotspelling, op) ? "$(spelled[1]) $(dotspelling[op]) $(spelled[2])" : "$op.($(join(spelled, ", ")))"))
    sc.shapes[i] = R
end

# The helper name and C form of a broadcast's function.
function broadcastop(f, n, E)
    for (g, op) in ((Base.:<, :lt), (Base.:<=, :le), (Base.:>, :gt), (Base.:>=, :ge), (Base.:(==), :eq), (Base.:!=, :ne),
                    (Base.:&, :and), (Base.:|, :or), (Base.:!, :not), (Base.ifelse, :ifelse))
        f === g && return op, op
    end
    f === Base.:+ && return :add, :add
    f === Base.:- && return n == 1 ? (:neg, :neg) : (:sub, :sub)
    f === Base.:* && return :mul, :mul
    f === Base.:/ && return :div, :div
    f === Base.:^ && return :pow, "pow"
    f === Base.abs && return :abs, E <: AbstractFloat ? "fabs" : "llabs"
    f === Base.max && return :max, "fmax"
    f === Base.min && return :min, "fmin"
    for (g, name) in ((Base.sqrt, "sqrt"), (Base.cbrt, "cbrt"), (Base.sin, "sin"), (Base.cos, "cos"), (Base.tan, "tan"),
                      (Base.asin, "asin"), (Base.acos, "acos"), (Base.atan, "atan"), (Base.sinh, "sinh"), (Base.cosh, "cosh"),
                      (Base.tanh, "tanh"), (Base.exp, "exp"), (Base.exp2, "exp2"), (Base.expm1, "expm1"), (Base.log, "log"),
                      (Base.log2, "log2"), (Base.log10, "log10"), (Base.log1p, "log1p"), (Base.floor, "floor"),
                      (Base.ceil, "ceil"), (Base.trunc, "trunc"), (Base.round, "rint"),
                      (Base.real, "real"), (Base.imag, "imag"), (Base.conj, "conj"), (Base.angle, "angle"))
        f === g && return Symbol(name == "rint" ? "round" : name), name
    end
    throw(ArgumentError("unsupported broadcast function: $f"))
end

# `conj.(A)` of the storage behind `src`, into `dest`: what a conjugate without a
# transpose comes to, since no tag says it.
function conjugate!(lines, sc::Scope, src, S::Type, dest; declaration::Bool)
    P = plain(S)
    declaration && emit!(lines, sc, declare(P, dest) * ";")
    emit!(lines, sc, "$(broadcasthelper!(sc.helpers, :conj, mathname(eltype(S), "conj"), (P,), P))($src, $dest);")
    step!(lines, sc, "$dest = conj.($src)")
end

# Emit the helper call for an array operation, writing into `dest`. An n-ary `+` or `*`
# (Julia parses `A + B + C` as one call) is chained through temps.
function arraycall!(lines, sc::Scope, i, ex::Expr, dest; declaration::Bool=false)
    f = callee(sc.ci, ex.args[1])
    args = ex.args[2:end]
    E = eltype(widen(sc.ci.ssavaluetypes[i]))
    if f === LinearAlgebra.cross
        types = (valuetype(sc, args[1]), valuetype(sc, args[2]))
        R = retype(types[1], E)
        declaration && emit!(lines, sc, declare(R, dest) * ";")
        emit!(lines, sc, "$(crosshelper!(sc.helpers, types, R))($(value(sc, args[1])), $(value(sc, args[2])), $dest);")
        step!(lines, sc, "$dest = $(value(sc, args[1])) × $(value(sc, args[2]))")
        sc.shapes[i] = R
        return
    end
    f === Base.getindex && return slice!(lines, sc, i, args, dest; declaration)
    if f === Base.literal_pow && length(args) == 3 && isarray(valuetype(sc, args[2]))
        # `A^2`, `A^3` on a square matrix: Julia's own definition is `A * A`, `A * A * A`.
        p = literal(sc, args[3])
        e = p isa Val ? typeof(p).parameters[1] : nothing
        e in (2, 3) || throw(ArgumentError("a matrix to the power $(something(e, "of a variable")): only `A^2` and `A^3` are supported; write the products out (statement $i)"))
        return arraycall!(lines, sc, i, Expr(:call, GlobalRef(Base, :*), fill(args[2], e)...), dest; declaration)
    end
    if f === Base.copy
        R = valuetype(sc, args[1])
        declaration && emit!(lines, sc, declare(R, dest) * ";")
        start = length(lines) + 1
        copy!(lines, sc, value(sc, args[1]), R, dest, R)
        step!(lines, sc, "$dest = $(value(sc, args[1]))"; from=start)
        sc.shapes[i] = R
        return
    end
    # `s \ A` is `A / s`; `A / s` is elementwise; anything else with `\` or `/` is a solve.
    f === Base.:\ && valuetype(sc, args[1]) <: Number && (args = [args[2], args[1]]; f = Base.:/)
    (f === Base.:\ || f === Base.inv || f === LinearAlgebra.pinv || (f === Base.:/ && isarray(valuetype(sc, args[2])))) && return solve!(lines, sc, i, f, args, dest; declaration)
    name = usercall!(sc, f, args)
    if name !== nothing
        R = widen(sc.ci.ssavaluetypes[i])
        declaration && emit!(lines, sc, declare(R, dest) * ";")
        emit!(lines, sc, "$name($(callargs(sc, args)), $dest);")
        step!(lines, sc, "$dest = $name($(callargs(sc, args)))")
        sc.shapes[i] = R
        return
    end
    # `sum(A; dims=1)`, `diff(v)`, `cumsum(A; dims=2)`: an operation along one dimension.
    if f === Core.kwcall || f in (Base.diff, Base.cumsum, Base.cumprod)
        kw = f === Core.kwcall ? literal(sc, args[1]) : (;)
        f === Core.kwcall && (f = callee(sc.ci, args[2]); args = args[3:end])
        return along!(lines, sc, i, f, args, kw, dest; declaration)
    end
    op = f === Base.:+ ? :add :
         f === Base.:- ? (length(args) == 1 ? :neg : :sub) :
         f === Base.:* ? :mul :
         f === Base.:/ ? :div :
         unknown(sc, f, args, i)
    # `A + 2I`, `A - I`, `2I - A`: a multiple of the identity on the diagonal.
    op in (:add, :sub) && length(args) == 2 && any(a -> literal(sc, a) isa LinearAlgebra.UniformScaling, args) &&
        return scaling!(lines, sc, i, op, args, dest; declaration)
    # The result's element type comes from Julia's promotion; its size from the IR if
    # the type carries one, otherwise from the operation's own rule.
    result(types) = (R = widen(sc.ci.ssavaluetypes[i]); shape(R) === nothing ? resulttype(op, types, E) : R)
    # An integer literal coefficient of a floating array takes the array's element type:
    # `-3A` is `mul_s_2x2(-3.0, A, out)`, not a mixed-type helper and an `int64_t`.
    function operand(x, other)
        x isa Integer && isarray(other) && eltype(other) <: AbstractFloat && return eltype(other), value(sc, eltype(other)(x))
        x isa Integer && isarray(other) && eltype(other) <: Complex && return real(eltype(other)), value(sc, real(eltype(other))(x))   # `2y` on complex: a real 2.0
        return valuetype(sc, x), value(sc, x)
    end
    acc = args[1]
    acctype, accname = length(args) >= 2 ? operand(acc, valuetype(sc, args[2])) : (valuetype(sc, acc), value(sc, acc))
    # `A + B + C` accumulates in the destination, as a person would write it, when every
    # step has the destination's type, the helper lets its output alias an input (the
    # elementwise ones do; a matrix product's output is `restrict`), and no later operand
    # is the destination itself. Otherwise each step but the last gets a temp.
    steps = Type[]                    # each step's own result type; the last is the statement's
    aliasable = true
    let t = acctype
        for (n, a) in enumerate(args[2:end])
            at = operand(a, t)[1]
            op === :mul && isarray(t) && isarray(at) && (aliasable = false)
            # A step on the way has the element type Julia gives that step, not the final one:
            # `a + b + c` on two integer vectors and a float one adds the integers as integers.
            elt(X) = X <: AbstractArray ? eltype(X) : X
            t = n == length(args) - 1 ? result((t, at)) : resulttype(op, (t, at), promote_type(elt(t), elt(at)))
            t === nothing && throw(ArgumentError("a row times a column in the middle of a product, `v' * w * A`: that part is a number and the rest is an array. Give the number a name first, `s = v' * w`, or write `dot(v, w) * A` (statement $i)"))
            push!(steps, t)
        end
    end
    alike(T) = shape(T) == shape(steps[end]) && eltype(T) == eltype(steps[end])   # the same array, however the type spells it
    inplace = length(args) > 2 && aliasable && all(alike, steps) && all(a -> operand(a, acctype)[2] != dest, args[2:end])
    inplace && declaration && emit!(lines, sc, declare(steps[end], dest) * ";")
    R = acctype
    for (n, a) in enumerate(args[2:end])
        last = n == length(args) - 1
        atype, aname = operand(a, acctype)
        types = (acctype, atype)
        R = steps[n]
        out = last || inplace ? dest : temp!(sc, nothing, unique([contribution(sc, acc); contribution(sc, a)]))
        !inplace && (last ? declaration : true) && emit!(lines, sc, declare(R, out) * ";")
        # A folded negation (`foldable`) lands on the scalar operand.
        isnegated(sc, acc) && (aname = negate(aname))
        isnegated(sc, a) && (accname = negate(accname))
        emit!(lines, sc, "$(helper!(sc.helpers, op, types, R))($accname, $aname, $out);")
        sign = Dict(:add => "+", :sub => "-", :mul => "*", :div => "/")[op]
        accname == out && !isnegated(sc, acc) && !isnegated(sc, a) ?
            step!(lines, sc, "$out $sign= $(spell(atype, aname))") :
            step!(lines, sc, "$out = $(spell(acctype, accname)) $sign $(spell(atype, aname))")
        accname, acctype = out, R
    end
    if length(args) == 1
        R = result((acctype,))
        declaration && emit!(lines, sc, declare(R, dest) * ";")
        emit!(lines, sc, "$(helper!(sc.helpers, op, (acctype,), R))($accname, $dest);")
        step!(lines, sc, "$dest = -$(spell(acctype, accname))")
    end
    sc.shapes[i] = R
end

# `A \ b`, `inv(A)`, and the same through `cholesky(A)` or `lu(A)`: one helper each,
# with the factorization inside it. Sizes 1–3 are written out; from 4 on it's LU with
# partial pivoting or Cholesky, which can fail on a singular or non-positive-definite
# matrix — that prints Julia's exception and stops, so the output needs `stdio.h` and
# `stdlib.h`.
function solve!(lines, sc::Scope, i, f, args, dest; declaration::Bool=false)
    ci = sc.ci
    x = args[1]
    method = :lu
    if x isa Core.SSAValue && ci.code[x.id] isa Expr && ci.code[x.id].head === :call
        g = callee_or_nothing(ci, ci.code[x.id].args[1])
        if g === LinearAlgebra.cholesky || g === LinearAlgebra.lu
            method = g === LinearAlgebra.cholesky ? :llt : :lu
            x = ci.code[x.id].args[2]
        end
    end
    if f === Base.:/
        # `B / A`: every row of `B` against `Aᵀ`.
        B, A = valuetype(sc, args[1]), valuetype(sc, args[2])
        R = widen(ci.ssavaluetypes[i])
        shape(A)[1] >= 4 && union!(sc.headers, ("stdio.h", "stdlib.h", "math.h"))
        declaration && emit!(lines, sc, declare(R, dest) * ";")
        emit!(lines, sc, "$(rsolvehelper!(sc.helpers, B, A, R))($(value(sc, args[1])), $(value(sc, args[2])), $dest);")
        step!(lines, sc, "$dest = $(spell(B, value(sc, args[1]))) / $(spell(A, value(sc, args[2])))")
        sc.shapes[i] = R
        return
    end
    T = valuetype(sc, x)
    R = widen(ci.ssavaluetypes[i])
    n = shape(T)[1]
    (n >= 4 || method == :llt || f === LinearAlgebra.pinv || !allequal(shape(T))) && union!(sc.headers, ("stdio.h", "stdlib.h", "math.h"))
    if f === LinearAlgebra.pinv
        declaration && emit!(lines, sc, declare(R, dest) * ";")
        emit!(lines, sc, "$(pinvhelper!(sc.helpers, T, R))($(value(sc, x)), $dest);")
        step!(lines, sc, "$dest = pinv($(spell(T, value(sc, x))))")
        sc.shapes[i] = R
        return
    end
    if f === Base.inv
        name = method == :llt ? invLLThelper!(sc.helpers, T, R) : invhelper!(sc.helpers, T, R)
        declaration && emit!(lines, sc, declare(R, dest) * ";")
        emit!(lines, sc, "$name($(value(sc, x)), $dest);")
        step!(lines, sc, "$dest = $(spell(T, value(sc, x)))⁻¹")
    else
        B = valuetype(sc, args[2])
        name = method == :llt ? solveLLThelper!(sc.helpers, T, B, R) : solvehelper!(sc.helpers, T, B, R)
        declaration && emit!(lines, sc, declare(R, dest) * ";")
        emit!(lines, sc, "$name($(value(sc, x)), $(value(sc, args[2])), $dest);")
        step!(lines, sc, "$dest = $(spell(T, value(sc, x))) \\ $(spell(B, value(sc, args[2])))")
    end
    sc.shapes[i] = R
end

# `A[i, :]`, `A[:, j]`, `v[2:4]`, `A[1:2, 2:3]`, `A[i, 2:3]`: a copy of part of an array,
# in any dimension, written inline into `dest`. Each index is a scalar (that dimension
# is dropped), a colon, or a literal range.
function slice!(lines, sc::Scope, i, args, dest; declaration::Bool=false)
    A, idx = args[1], args[2:end]
    T = valuetype(sc, A)
    length(idx) == ndims(T) || throw(ArgumentError("$(length(idx)) indices into a $(ndims(T))-dimensional array (statement $i)"))
    spans = Any[span(sc, T, d, k) for (d, k) in enumerate(idx)]
    R = widen(sc.ci.ssavaluetypes[i])
    shape(R) === nothing && (R = shaped(eltype(T), Tuple(s.extent for s in spans if !s.scalar)))
    declaration && emit!(lines, sc, declare(R, dest) * ";")
    start = length(lines) + 1
    slice!(lines, sc, value(sc, A), T, spans, dest, R)
    step!(lines, sc, "$dest = $(value(sc, A))[$(join((indexnotation(sc, k) for k in idx), ", "))]"; from=start)
    sc.shapes[i] = R
end

# One index as the Julia wrote it — `:`, `2:3`, or the expression — for a step comment.
function indexnotation(sc::Scope, k)
    x = literal(sc, k)
    x isa Colon && return ":"
    x isa AbstractUnitRange && return "$(first(x)):$(last(x))"
    x isa AbstractVector && return "[" * join(x, ", ") * "]"
    k isa Integer && return string(k)
    return first(expression(sc, k))
end

# One index of a slice along dimension `d` of `T`, as the 0-based C offset it starts at
# and the extent it covers: a scalar covers 1 (and the dimension is dropped), a colon
# the whole dimension, a literal range its length. A list of indices is a gather over
# `extent` positions, with no one offset: `[1, 3]` written out is the list of 0-based
# offsets, and an integer vector held at run time, `v[idx]`, the name of that C array.
function span(sc::Scope, T::Type, d, k)
    x = literal(sc, k)
    x isa Colon && return (offset="0", extent=extent(T, d), scalar=false, list=nothing)
    x isa AbstractUnitRange && return (offset=string(first(x) - 1), extent=length(x), scalar=false, list=nothing)
    if x isa AbstractVector{<:Integer}
        all(j -> 1 <= j <= extent(T, d), x) || throw(ArgumentError("the index list $x runs outside dimension $d of a $(describe(T)) (line $(sc.stmtline[sc.current]))"))
        return (offset="", extent=length(x), scalar=false, list=[j - 1 for j in x])
    end
    K = valuetype(sc, k)
    if isarray(K)
        ndims(K) == 1 && eltype(K) <: Integer && shape(K) !== nothing ||
            throw(ArgumentError("an index is a scalar, a range, `:`, or a vector of integers of a known length, not a $(shape(K) === nothing ? string(K) : describe(K)) (line $(sc.stmtline[sc.current]))"))
        return (offset="", extent=extent(K, 1), scalar=false, list=value(sc, k))
    end
    return (offset=zerobased(sc, k), extent=1, scalar=true, list=nothing)
end

# `A[2, :] = v`, `A[:, 3:4] = B`, `v[2:3] = w`: part of a mutable array assigned from a
# whole array, written inline. Julia requires the shapes to match; so does this.
function setslice!(lines, sc::Scope, i, A, src, idx)
    T, S = valuetype(sc, A), valuetype(sc, src)
    length(idx) == ndims(T) || throw(ArgumentError("$(length(idx)) indices into a $(ndims(T))-dimensional array (statement $i)"))
    spans = Any[span(sc, T, d, k) for (d, k) in enumerate(idx)]
    spanned = [d for d in eachindex(spans) if !spans[d].scalar]
    Tuple(spans[d].extent for d in spanned) == Tuple(extents(S)) || throw(ArgumentError("assigning a $(describe(S)) into a $(join((spans[d].extent for d in spanned), "×")) slice (statement $i)"))
    source = value(sc, src)
    if mentions(sc, value(sc, A), src)
        # The source is the target's own storage: copy it first.
        t = temp!(sc, nothing, contribution(sc, src))
        emit!(lines, sc, declare(S, t) * ";")
        copy!(lines, sc, source, S, t, S)
        source = t
    end
    start = length(lines) + 1
    setslice!(lines, sc, value(sc, A), T, spans, source, S)
    step!(lines, sc, "$(value(sc, A))[$(join((indexnotation(sc, k) for k in idx), ", "))] = $source"; from=start)
end

# A Julia index as a 0-based C expression.
function zerobased(sc::Scope, k)
    k isa Integer && return string(k - 1)
    text, p = expression(sc, k)
    return (p < ADD ? "($text)" : text) * " - 1"
end

isarray(T) = T <: AbstractArray

# The named variables behind a call's arguments, for temp naming.
parts(sc::Scope, ex::Expr) = unique(reduce(vcat, (contribution(sc, a) for a in ex.args[2:end]); init=String[]))

# What the temp holding a call's result is named after. For a call to a function that
# has a C function of its own: the variable that function returns, when it returns one
# (`return ω` gives `temp1_omega`); failing that, for a tuple being unpacked, the
# function itself (`return x, ẋ` in `step` gives `temp1_step`). Otherwise — any other
# call, or a function returning an expression — the operands, like any operation.
function callparts(sc::Scope, ex::Expr)
    r = userinstance!(sc, callee_or_nothing(sc.ci, ex.args[1]), ex.args[2:end])
    r === nothing && return parts(sc, ex)
    mi, _, cname = r
    n = returnname!(sc.prog, mi)
    n !== nothing && return [n]
    istuple(returntype(mi)) && return [cname]
    return parts(sc, ex)
end

# The variable a user function returns, as its C name, when every return is a plain
# variable of the author's — `return ω`, or `ω = …` as the last line. Nothing for a
# returned expression, a tuple literal, another call, or returns that disagree.
function returnname!(prog::Program, mi::Core.MethodInstance)
    haskey(prog.returned, mi) && return prog.returned[mi]
    ci, _ = only(Base.code_typed_by_type(mi.specTypes; optimize=false))
    name = nothing
    for (r, st) in enumerate(ci.code)
        st isa Core.ReturnNode && isdefined(st, :val) || continue
        v = returnslot(ci, r)
        v !== nothing && v > ci.nargs && !startswith(string(ci.slotnames[v]), "#") || (name = nothing; break)
        s = identifier(string(ci.slotnames[v]))
        name === nothing ? (name = s) : name == s || (name = nothing; break)
    end
    prog.returned[mi] = name
    return name
end

# Is the tuple made at statement `i` used only as an argument to the user's functions?
function consumedbycalls(sc::Scope, i)
    users = [consumer(st) for st in sc.ci.code if uses(st, i)]
    isempty(users) && return false
    return all(st -> st isa Expr && st.head === :call && userinstance!(sc, callee_or_nothing(sc.ci, st.args[1]), st.args[2:end]) !== nothing, users)
end

# The expression a statement computes: the right-hand side of a store, else itself.
consumer(st) = st isa Expr && st.head === :(=) ? st.args[2] : st

# Is SSA value `i` used only as an index — among the indices of `getindex` and
# `setindex!` calls, never as the array or the value?
function onlyindexes(sc::Scope, i)
    for st in sc.ci.code
        uses(st, i) || continue
        c = consumer(st)
        iscall(c, Base.getindex)  && !uses(c.args[2], i) && continue
        iscall(c, Base.setindex!) && !uses(c.args[2], i) && !uses(c.args[3], i) && continue
        return false
    end
    return true
end

# The C struct a tuple-returning function returns: named after the function, `step_t`,
# with fields named after the variables it returns (`return x, ẋ` gives `x`, `xdot`).
# A function that returns another function's tuple straight on returns that function's
# struct. Otherwise — an expression returned, or returns that disagree — the fields are
# positional letters. The typedef is written once, when first asked for.
function returnkind!(prog::Program, mi::Core.MethodInstance, cname::AbstractString)
    haskey(prog.kinds, mi) && return prog.kinds[mi]
    ci, R = only(Base.code_typed_by_type(mi.specTypes; optimize=false))
    R = widen(R)
    fallback = Kind(structname(R), fieldcnames(R))
    prog.kinds[mi] = fallback                      # against a cycle of pass-throughs
    rawtype(t) = t isa Core.Const ? typeof(t.val) : t isa Core.PartialStruct ? t.typ : t
    slotname(a) = a isa Core.SSAValue && ci.code[a.id] isa Core.SlotNumber ? string(ci.slotnames[ci.code[a.id].id]) :
                  a isa Core.SlotNumber ? string(ci.slotnames[a.id]) : nothing
    names = nothing
    inherited = nothing
    for st in ci.code
        st isa Core.ReturnNode && isdefined(st, :val) && st.val isa Core.SSAValue || continue
        def = ci.code[st.val.id]
        # `x = (y, z); return x`: through the variable to what it was assigned, when
        # that happened once.
        if def isa Core.SlotNumber
            stores = [s for s in ci.code if s isa Expr && s.head === :(=) && s.args[1].id == def.id]
            length(stores) == 1 || (names = nothing; break)
            def = stores[1].args[2]
            def isa Core.SSAValue && (def = ci.code[def.id])
        end
        def isa Expr && def.head === :call || (names = nothing; break)
        f = callee_or_nothing(ci, def.args[1])
        if f === Core.tuple
            ns = [slotname(a) for a in def.args[2:end]]
            any(isnothing, ns) && (names = nothing; break)
            names === nothing && inherited === nothing ? (names = ns) : names == ns || (names = nothing; break)
        elseif f isa Function && !(nameof(Base.moduleroot(parentmodule(f))) in known)
            types = [rawtype(valuetype_ir(ci, a)) for a in def.args[2:end]]
            all(T -> T isa Type && isconcretetype(T), types) || (names = nothing; break)
            spec = Any[T <: Shaped ? T : juliatype(T) for T in types]
            r = register!(prog, f, spec)
            r === nothing && (names = nothing; break)
            k = returnkind!(prog, r[1], r[3])
            inherited === nothing && names === nothing ? (inherited = k) : inherited == k || (names = nothing; inherited = nothing; break)
        else
            names = nothing; break
        end
    end
    kind = inherited !== nothing && names === nothing ? inherited :
           names !== nothing ? Kind(free(identifier(cname) * "_t", union(prog.names, Set(structname(T) for (T, _) in prog.structs), prog.yielded, reserved)), identifiers(names)) : fallback
    if kind.cname != fallback.cname && !any(p -> p.first == kind.cname, prog.tupledefs) && inherited === nothing
        for F in R.parameters
            structdef!(prog, F)
        end
        listed = length(kind.fields) == 1 ? kind.fields[1] : length(kind.fields) == 2 ? join(kind.fields, " and ") : join(kind.fields[1:end-1], ", ") * ", and " * kind.fields[end]
        push!(prog.tupledefs, kind.cname => "/// the return value of $cname: $listed, as one struct since C returns one value\n" *
                                            "typedef struct {\n" * join("    " .* declare.(collect(R.parameters), kind.fields) .* ";", "\n") * "\n} $(kind.cname);\n")
    end
    kind.cname == fallback.cname && structdef!(prog, R)
    prog.kinds[mi] = kind
    return kind
end

"""
    temp!(sc, i, parts) -> name

Name the intermediate value `i`, computed from the named variables `parts`.

Temps are `temp1`, `temp2`, … in order of creation within a function, with the names
of the variables used directly in the calculation appended: `temp1_a_b = a + b`.
Literals contribute nothing (`temp2_a = a + 58.3`), a variable appears at most once
(`temp3_a = a * a`), and a temp passes along only its own suffix, never its base
(`temp4_a_b = temp3_a + b`; `temp5_a = temp2 + a`).

A number is skipped if any of the user's own variables is `temp<N>` or `temp<N>_…`,
so there's never confusion about which is which. If the mangled name would be longer
than the scope's limit, the suffix is dropped and the temp is just `temp<N>`.

There is one rule for what any value contributes, temp or not: its name with any
`temp<N>_` chopped off, split into pieces at `_`. So a user's own `temp4_joel_was_here`
contributes `joel_was_here` exactly as one of ours would, and a plain `temp3` contributes
nothing. See `doc/naming.md`.

`i` may be `nothing` for a temp that doesn't stand for any SSA value.
"""
function temp!(sc::Scope, i, parts)
    local name
    while true
        sc.counter += 1
        sc.counter in sc.blocked && continue
        base = "temp$(sc.counter)"
        name = isempty(parts) || !sc.prog.suffix ? base : base * "_" * join(parts, "_")
        length(name) > sc.limit && (name = base)
        # A global of the author's called `temp1_n` that this function reads: a temp of that
        # name would capture every later read of it. The number moves on.
        name in sc.outer || base in sc.outer || break
    end
    i === nothing || (sc.expr[i] = name)
    return name
end

# The name for an unnamed result. Only one per block; a second falls back to a temp.
function result!(sc::Scope, i)
    name = sc.result
    sc.result = ""
    isempty(name) && return temp!(sc, i, String[])
    sc.expr[i] = name
    return name
end

# The one variable every `return` of the function returns, or nothing.
function returnedslot(ci)
    slot = nothing
    for (r, st) in enumerate(ci.code)
        st isa Core.ReturnNode && isdefined(st, :val) || continue
        v = returnslot(ci, r)
        v === nothing && return nothing
        slot === nothing ? (slot = v) : slot == v || return nothing
    end
    return slot
end

# Is SSA value `i` used only to be stored in a variable that is then only returned?
function storedforreturn(sc::Scope, i)
    ci = sc.ci
    users = [(u, st) for (u, st) in enumerate(ci.code) if uses(st, i)]
    length(users) == 1 && users[1][2] isa Expr && users[1][2].head === :(=) || return false
    slot = users[1][2].args[1].id
    reads = [u for (u, st) in enumerate(ci.code) if st isa Core.SlotNumber && st.id == slot]
    return !isempty(reads) && all(r -> onlyreturned(ci, r), reads)
end

# Is SSA value `i` used by nothing but return statements?
function onlyreturned(ci, i)
    users = [st for st in ci.code if uses(st, i)]
    return !isempty(users) && all(st -> st isa Core.ReturnNode, users)
end

# The pieces an IR value contributes to a temp's suffix. Literals contribute nothing.
# Anything named contributes its name, minus a leading `temp<N>` (and its `_`), split
# at `_` — the same rule whether the name is one of our temps or the user's own.
function contribution(sc::Scope, x)
    x isa Core.SSAValue && sc.ci.code[x.id] isa GlobalRef && return contribution(sc, sc.ci.code[x.id])
    x isa GlobalRef && (v = getfield(x.mod, x.name); !builtin(x, v)) &&
        return filter(!isempty, split(global!(sc.prog, owner(x), x.name, v).cname, "_"))
    x isa Core.SSAValue || x isa Core.SlotNumber || return String[]
    x isa Core.SSAValue && !(x.id in sc.inlined) && !haskey(sc.expr, x.id) && return String[]   # a constant load
    x isa Core.SSAValue && haskey(sc.choices, x.id) && return String[]
    x isa Core.SSAValue && haskey(sc.alias, x.id) && return sc.alias[x.id] isa Tuple ? String[] : contribution(sc, sc.alias[x.id])
    x isa Core.SSAValue && x.id in sc.inlined && return unique(reduce(vcat, (contribution(sc, a) for a in sc.ci.code[x.id].args[2:end]); init=String[]))
    # A field read contributes its path, p.x -> p_x. The `_local` of a variable that gave
    # way is ours, not the author's: a temp computed from `x_local` is named after `x`.
    name = replace(value(sc, x), r"^temp\d+_?" => "", r"_local_*$" => "", "->" => "_", "." => "_")
    return filter(!isempty, split(name, "_"))
end

# Can SSA value `i`, which holds the value of `slot` at that point, be written as the
# slot's name at every use? Only if the slot isn't reassigned in between. The textual
# scan is sound for Julia's structured lowering: everything executed between a value's
# definition and a use of it lies between them in the statement list too.
function stable(ci, i, slot)
    for (u, st) in enumerate(ci.code)
        u > i && uses(st, i) || continue
        any(k -> assigns(ci.code[k], slot), i+1:u-1) && return false
    end
    return true
end

# Is `%i = -x`, an array negation, consumed only by a scalar multiply or divide —
# `-x / s`, `-x * s`, `s * -x`? Then the sign moves onto the scalar: `x / (-s)` is
# bit-for-bit `(-x) / s`, since IEEE rounding is symmetric, and a helper call is saved.
function foldable(sc::Scope, i, st::Expr)
    st.head === :call && callee_or_nothing(sc.ci, st.args[1]) === Base.:- && length(st.args) == 2 || return false
    users = [u for (u, s) in enumerate(sc.ci.code) if uses(s, i)]
    length(users) == 1 || return false
    use = sc.ci.code[users[1]]
    use isa Expr && use.head === :(=) && (use = use.args[2])
    use isa Expr && use.head === :call && length(use.args) == 3 || return false
    f = callee_or_nothing(sc.ci, use.args[1])
    scalar(a) = !isarray(valuetype(sc, a))
    f === Base.:/ && return use.args[2] == Core.SSAValue(i) && scalar(use.args[3])
    f === Base.:* && return use.args[2] == Core.SSAValue(i) ? scalar(use.args[3]) : scalar(use.args[2])
    return false
end

isnegated(sc::Scope, a) = a isa Core.SSAValue && a.id in sc.negated

# `-s` for a scalar C expression: a name or number takes the sign directly, anything
# else in parentheses; a leading sign is cancelled rather than doubled.
negate(s::AbstractString) = startswith(s, "-") ? s[2:end] : occursin(r"^[\w.]+(\[[^\]]*\])*$", s) ? "-" * s : "-(" * s * ")"

uses(x, i) = x isa Core.SSAValue   ? x.id == i :
             x isa Expr            ? any(a -> uses(a, i), x.args) :
             x isa Core.ReturnNode ? isdefined(x, :val) && uses(x.val, i) :
             x isa Core.GotoIfNot  ? uses(x.cond, i) : false

assigns(st, slot) = st isa Expr && st.head === :(=) && st.args[1].id == slot

# C precedence levels used by `render`.
const PRIMARY, UNARY, MUL, ADD, SHIFT, REL, EQ, BAND, BXOR, BOR, LAND, LOR = 15, 14, 13, 12, 11, 10, 9, 8, 7, 6, 5, 4
include("idiom.jl")     # scalar functions that are one C expression, a row each

"""
    render(sc, i, ex) -> (text, precedence)

The C expression for the scalar call `ex`, whose result is SSA value `i`.
"""
function render(sc::Scope, i, ex::Expr)
    text, p = rendered(sc, i, ex)
    # C does its arithmetic on nothing narrower than `int`: `a + b` on two `uint8_t` is an
    # `int` that can be 300, where Julia's is a `UInt8` that wrapped to 44. Stored into a
    # `uint8_t` it wraps the same; inside a larger expression it doesn't. So arithmetic whose
    # Julia type is narrower than `int` is cast to that type where it is written.
    T = widen(sc.ci.ssavaluetypes[i])
    T <: Union{Int8, UInt8, Int16, UInt16} && callee_or_nothing(sc.ci, ex.args[1]) in (Base.:+, Base.:-, Base.:*, Base.:<<, Base.:~, Base.literal_pow) || return text, p
    return "($(ctype(T)))" * (p < UNARY ? "($text)" : text), UNARY
end

function rendered(sc::Scope, i, ex::Expr)
    ci = sc.ci
    f = callee(ci, ex.args[1])
    args = ex.args[2:end]
    # A size the transpiler knows, written where it is used: `v[end]`, `A[end, 1]`.
    if f in (Base.lastindex, Base.firstindex, Base.length, Base.size)
        v = literal(sc, Core.SSAValue(i))
        v isa Integer && return (string(v), PRIMARY)
    end
    T = widen(ci.ssavaluetypes[i])
    n = length(args)
    # `a + -b` is written `a - b`, and `a - -b` is `a + b`: exact, since a negation
    # is, and what a person writes. A negation is what a right operand that starts
    # with `-` is: anything binding less tightly than `*` has been parenthesised.
    # With an integer standing in for `bool` (the `bool` option), a truth value read from
    # storage — a parameter, a field, an element, a global — is any nonzero value, so
    # where it enters arithmetic or a comparison it is read as `(b != 0)`. One computed
    # here, a comparison's result, is already 0 or 1.
    function stored(x)
        x isa Core.SlotNumber && return true
        x isa Core.SSAValue || return false
        st = ci.code[x.id]
        (st isa Core.SlotNumber || st isa GlobalRef) && return true
        st isa Expr && st.head === :call && callee_or_nothing(ci, st.args[1]) in (Base.getfield, Core.getfield, Base.getproperty, Base.getindex)
    end
    truth(x, prec; right=false) = booltype[] !== Bool && valuetype(sc, x) === Bool && stored(x) ? "($(operand(sc, x, EQ)) != 0)" : operand(sc, x, prec; right)
    # Julia's integer literal is an `Int64`; C's is an `int`. `1 << k` and `ms * 1000` on a
    # `uint32_t` are 32-bit arithmetic in C and 64-bit in Julia. Where the result is 64 bits
    # wide and nothing that decides C's type is, the first operand is cast: `(int64_t)1 << k`.
    # Not where the 32 bits can't be outgrown: `2 * 3`, `c - 'a'`, two `uint8_t`s added.
    wide(a) = a isa Integer ? !(typemin(Int32) <= a <= typemax(Int32)) : sizeof(valuetype(sc, a)) >= 8
    reach(a) = a isa Integer ? abs(big(a)) : (V = valuetype(sc, a); V === Bool ? big(1) : V === Char ? big(0x10ffff) : big(2)^(8 * sizeof(V)))
    outgrown(sym) = sym == "<<" || (sym == "*" ? prod(reach, args) : sum(reach, args)) >= big(2)^31
    function op(sym, prec)
        if sym in ("+", "-", "*", "<<") && T <: Union{Int64, UInt64} && !any(wide, sym == "<<" ? args[1:1] : args) && outgrown(sym)
            s = "($(ctype(T)))" * truth(args[1], UNARY)
            for a in args[2:end]
                s *= " $sym " * truth(a, prec; right=true)
            end
            return s, prec
        end
        s = truth(args[1], prec)
        for a in args[2:end]
            t = truth(a, prec; right=true)
            s *= sym in ("+", "-") && startswith(t, "-") ? (sym == "+" ? " - " : " + ") * t[2:end] : " $sym " * t
        end
        return s, prec
    end
    # `-(-x)` is `x`, exactly.
    unary(sym) = (t = operand(sc, args[1], UNARY); sym == "-" && startswith(t, "-") ? (t[2:end], PRIMARY) : (sym * t, UNARY))
    # A `math.h` function on a `float` is the `f` variant: `sqrtf`, `fabsf`, `powf`.
    # The variant is the result's, which is Julia's promotion of the arguments: `max(x32, y64)` is
    # `fmax`, not `fmaxf`. A complex argument names its own (`cabs` of a complex gives a real).
    variant() = (k = findfirst(a -> valuetype(sc, a) <: Complex, args); k !== nothing ? valuetype(sc, args[k]) : T <: AbstractFloat ? T : valuetype(sc, args[1]))
    fn(name, hdr="math.h") = (push!(sc.headers, hdr); ("$(hdr == "math.h" ? mathname(variant(), name) : name)(" * join((expression(sc, a)[1] for a in args), ", ") * ")", PRIMARY))
    # `max(a, b, c)` is `max(max(a, b), c)`, as Julia folds it.
    function folded(name)
        push!(sc.headers, "math.h")
        acc = expression(sc, args[1])[1]
        for a in args[2:end]
            acc = "$(mathname(variant(), name))($acc, $(expression(sc, a)[1]))"
        end
        return acc, n == 1 ? expression(sc, args[1])[2] : PRIMARY
    end
    # A signed and an unsigned integer together: Julia compares and divides them as the numbers
    # they are, and C converts the signed one to unsigned first, so that `-1 < 1u` is false.
    # Harmless where the signed type holds every value of the unsigned one, and for a literal
    # that isn't negative. Refused otherwise: there is no C operator that means what Julia means.
    function signedness(what)
        Ts = [(a, valuetype(sc, a)) for a in args]
        any(((a, U),) -> U <: Unsigned && sizeof(U) >= 4 &&
                         any(((b, S),) -> S <: Signed && sizeof(U) >= sizeof(S) && !(literal(sc, b) isa Integer && literal(sc, b) >= 0), Ts), Ts) &&
            throw(ArgumentError("$what between a signed and an unsigned integer ($(join((string(X) for (_, X) in Ts), ", "))): Julia takes them as the numbers they are, C converts the signed one to unsigned first, and a negative one goes wrong. Convert one side so that both are alike, `Int64(u)` or `UInt64(s)` (statement $i)"))
    end
    floating = T <: AbstractFloat
    # Complex scalars are C99's: the operators as they are, the functions with a `c`.
    cplx = T <: Complex || any(a -> valuetype(sc, a) <: Complex, args)
    if cplx
        f in (Base.real, Base.imag, Base.conj, Base.abs, Base.angle) && n == 1 && valuetype(sc, args[1]) <: Complex &&
            return (push!(sc.headers, "complex.h"); ("$(mathname(valuetype(sc, args[1]), f === Base.abs ? "fabs" : string(nameof(f))))($(expression(sc, args[1])[1]))", PRIMARY))
        f === Base.adjoint && n == 1 && valuetype(sc, args[1]) <: Complex && return "$(mathname(valuetype(sc, args[1]), "conj"))($(expression(sc, args[1])[1]))", PRIMARY
        f === Base.abs2 && n == 1 && valuetype(sc, args[1]) <: Complex && return "$(abs2helper!(sc.helpers, valuetype(sc, args[1])))($(expression(sc, args[1])[1]))", PRIMARY
        (f === Base.complex || f isa Type && f <: Complex) && n == 2 && return "$(T === ComplexF32 ? "CMPLXF" : "CMPLX")($(expression(sc, args[1])[1]), $(expression(sc, args[2])[1]))", PRIMARY
        if f in (Base.getproperty, Core.getfield) && n == 2 && valuetype(sc, args[1]) <: Complex
            field = literal(sc, args[2])
            field in (:re, :im) || throw(ArgumentError("a complex number has fields re and im, not $field (statement $i)"))
            return "$(mathname(valuetype(sc, args[1]), field === :re ? "real" : "imag"))($(expression(sc, args[1])[1]))", PRIMARY
        end
    elseif f in (Base.real, Base.conj) && n == 1 && T <: Real
        return expression(sc, args[1])                # a real's real part and conjugate are itself
    elseif f === Base.float && n == 1
        return valuetype(sc, args[1]) <: AbstractFloat ? expression(sc, args[1]) : ("($(ctype(T)))" * operand(sc, args[1], UNARY), UNARY)
    elseif f === Base.imag && n == 1 && T <: Real
        return value(sc, zero(T)), PRIMARY
    end
    # `zero(x)`, `one(T)`: the literal of the result's type.
    f in (Base.zero, Base.one) && n == 1 && T <: Number && return value(sc, f === Base.zero ? zero(T) : one(T)), PRIMARY

    # `norm(v, 1)`, `norm(v, Inf)`, `norm(v, 2)` with the order written out; `mean`, `var`, `std`
    # of a real array, which are `Statistics`' and known by name, the package not being loaded here.
    statistic = f isa Function && nameof(parentmodule(f)) === :Statistics && nameof(f) in (:mean, :var, :std) ? nameof(f) : nothing
    if n == 2 && f === LinearAlgebra.norm && isarray(valuetype(sc, args[1])) && literal(sc, args[2]) in (1, 2, Inf) && !(eltype(valuetype(sc, args[1])) <: Complex) ||
       n == 1 && statistic !== nothing && isarray(valuetype(sc, args[1])) && eltype(valuetype(sc, args[1])) <: AbstractFloat
        op = statistic !== nothing ? statistic : literal(sc, args[2]) == 1 ? :norm1 : literal(sc, args[2]) == 2 ? :norm : :normInf
        push!(sc.headers, "math.h")
        sc.math[i] = statistic !== nothing ? "$op($(value(sc, args[1])))" : "‖$(value(sc, args[1]))‖" * (op == :norm1 ? "₁" : op == :normInf ? "∞" : "")
        return "$(reducehelper!(sc.helpers, op, valuetype(sc, args[1]), T))($(value(sc, args[1])))", PRIMARY
    end
    # A reduction: a helper that returns the scalar.
    if f in (Base.sum, Base.prod, Base.maximum, Base.minimum, Base.any, Base.all, LinearAlgebra.norm, Base.count, Base.argmax, Base.argmin, Base.extrema, LinearAlgebra.tr) &&
       n == 1 && isarray(valuetype(sc, args[1]))
        op = f === LinearAlgebra.norm ? :norm : Symbol(nameof(f))
        op == :tr && !(ndims(valuetype(sc, args[1])) == 2 && allequal(shape(valuetype(sc, args[1])))) && throw(ArgumentError("tr needs a square matrix, got a $(describe(valuetype(sc, args[1]))) (statement $i)"))
        op == :norm && push!(sc.headers, "math.h")
        op in (:argmax, :argmin) && ndims(valuetype(sc, args[1])) != 1 && throw(ArgumentError("$op of a $(describe(valuetype(sc, args[1]))) is a CartesianIndex in Julia; not supported (statement $i)"))
        op == :extrema && structdef!(sc.prog, T)   # a (min, max) tuple, returned as a struct
        sc.math[i] = "$op($(value(sc, args[1])))"
        return "$(reducehelper!(sc.helpers, op, valuetype(sc, args[1]), T))($(value(sc, args[1])))", PRIMARY
    end
    # The determinant: a helper that returns the scalar.
    if f === LinearAlgebra.det && n == 1 && isarray(valuetype(sc, args[1]))
        sc.math[i] = "det($(spell(valuetype(sc, args[1]), value(sc, args[1]))))"
        return "$(dethelper!(sc.helpers, valuetype(sc, args[1]), T))($(value(sc, args[1])))", PRIMARY
    end
    # A dot product, or a row times a column: a helper that returns the scalar.
    if (f === LinearAlgebra.dot || f === Base.:*) && n == 2 && all(a -> isarray(valuetype(sc, a)), args) &&
       ndims(valuetype(sc, args[1])) == 1 && ndims(valuetype(sc, args[2])) == 1
        types = (valuetype(sc, args[1]), valuetype(sc, args[2]))
        f === Base.:* && !(isrow(types[1]) && !isrow(types[2])) && throw(ArgumentError("vector * vector is only defined for a row times a column (statement $i)"))
        name = scalarhelper!(sc.helpers, f === LinearAlgebra.dot ? :dot : :mul, types, T)
        sc.math[i] = f === LinearAlgebra.dot ? "$(value(sc, args[1])) ⋅ $(value(sc, args[2]))" : "$(spell(types[1], value(sc, args[1]))) * $(value(sc, args[2]))"
        return "$name($(value(sc, args[1])), $(value(sc, args[2])))", PRIMARY
    end

    # `Moon.a`: a module's global, read through `getproperty`; the same as a direct reference.
    if f === Base.getproperty && n == 2 && literal(sc, args[1]) isa Module
        return value(sc, GlobalRef(literal(sc, args[1]), literal(sc, args[2]))), PRIMARY
    end

    # Characters: the `ctype.h` classes and cases. Julia's classes are Unicode-aware and
    # C's are ASCII; for the ASCII characters `char` can hold, they agree.
    if n == 1 && valuetype(sc, args[1]) === Char
        for (g, name) in ((Base.isdigit, "isdigit"), (Base.isletter, "isalpha"), (Base.isspace, "isspace"), (Base.isuppercase, "isupper"),
                          (Base.islowercase, "islower"), (Base.isnumeric, "isdigit"), (Base.ispunct, "ispunct"), (Base.iscntrl, "iscntrl"),
                          (Base.isprint, "isprint"), (Base.isxdigit, "isxdigit"))
            f === g && return fn(name, "ctype.h")
        end
        f === Base.isascii && return "(unsigned char)$(operand(sc, args[1], UNARY)) < 128", REL
        if f === Base.uppercase || f === Base.lowercase
            push!(sc.headers, "ctype.h")
            return "(char)$(f === Base.uppercase ? "toupper" : "tolower")($(expression(sc, args[1])[1]))", UNARY
        end
    end
    # Strings: UTF-8 bytes in both languages. Compared with `strcmp`, measured with
    # `strlen` (code units) or a character count (`length`), indexed by byte.
    if any(a -> valuetype(sc, a) <: AbstractString, args)
        s = expression(sc, args[1])[1]
        if (f === Base.:(==) || f === Base.:!=) && n == 2
            push!(sc.headers, "string.h")
            return "strcmp($s, $(expression(sc, args[2])[1])) $(f === Base.:(==) ? "==" : "!=") 0", EQ
        end
        f === Base.length && n == 1 && return "$(lengthhelper!(sc.helpers))($s)", PRIMARY
        f in (Base.ncodeunits, Base.sizeof, Base.lastindex) && n == 1 && (push!(sc.headers, "string.h"); return "(int64_t)strlen($s)", UNARY)
        f === Base.firstindex && n == 1 && return "1", PRIMARY
        f === Base.isempty && n == 1 && return "$(operand(sc, args[1], PRIMARY))[0] == '\\0'", EQ
        f === Base.getindex && n == 2 && return "$(operand(sc, args[1], PRIMARY))[$(subscript(sc, args[2]))]", PRIMARY
        f === Base.codeunit && n == 2 && return "(uint8_t)$(operand(sc, args[1], PRIMARY))[$(subscript(sc, args[2]))]", UNARY
        throw(ArgumentError("unsupported operation on a string: $f (statement $i)"))
    end

    # An operator on the user's structs is the user's method: `mul(a, b)`; `a * b * c`,
    # one call in Julia through Julia's fold, is the two binary calls.
    if any(a -> isstruct(valuetype(sc, a)), args)
        name = usercall!(sc, f, args)
        name === nothing || (sc.math[i] = julian(sc, f, args); return "$name($(callargs(sc, args)))", PRIMARY)
        if n > 2 && (name = usercall!(sc, f, args[1:2])) !== nothing
            sc.math[i] = julian(sc, f, args)
            acc = "$name($(callargs(sc, args[1:2])))"
            for a in args[3:end]
                acc = "$name($acc, $(callargs(sc, [a])))"
            end
            return acc, PRIMARY
        end
    end

    # Arithmetic.
    f === Base.:* && n > 2 && any(a -> isarray(valuetype(sc, a)), args) &&
        throw(ArgumentError("a product of several arrays that comes to a number, `v' * A * w`, `s * v' * w`: write the array part first and then the number, `dot(v, A * w)`, `s * dot(v, w)` (statement $i)"))
    f === Base.:+ && return n == 1 ? expression(sc, args[1]) : op("+", ADD)
    f === Base.:- && return n == 1 ? unary("-") : op("-", ADD)
    f === Base.:* && return op("*", MUL)
    if f === Base.:/
        if all(a -> valuetype(sc, a) <: Integer, args)
            # Julia `/` always produces a float. C promotes an integer operand to the
            # other's floating type on its own, so only integer-by-integer needs help:
            # literals get `.0`, anything else a cast to the result type.
            parts = [a isa Integer ? "$a.0" : "($(ctype(T)))" * operand(sc, a, UNARY) for a in args]
            return join(parts, " / "), MUL
        end
        return op("/", MUL)
    end
    if f === Base.:\ && n == 2
        args = reverse(args)          # a \ b is b / a
        f = Base.:/
        return render(sc, i, Expr(:call, f, args...))
    end
    f in (Base.div, Base.rem, Base.mod) && signedness("`$(nameof(f))`")
    # `div` on floats is the quotient with its fraction dropped; `fld` and `cld` round it down and up.
    if f in (Base.div, Base.fld, Base.cld) && floating && n == 2
        push!(sc.headers, "math.h")
        return "$(mathname(T, f === Base.div ? "trunc" : f === Base.fld ? "floor" : "ceil"))($(op("/", MUL)[1]))", PRIMARY
    end
    f === Base.div && return op("/", MUL)
    f === Base.rem && return floating ? fn("fmod") : op("%", MUL)
    if f === Base.mod
        # On floats, Julia's `mod` takes the divisor's sign where C's `fmod` takes the
        # dividend's: a helper (`modhelper!`).
        floating && (push!(sc.headers, "math.h"); return fn(modhelper!(sc.helpers, T), ""))
        T <: Unsigned && return op("%", MUL)          # nothing is negative: `mod` is `rem`, and `+ b` could overflow
        a, b = operand(sc, args[1], MUL), operand(sc, args[2], MUL; right=true)
        return "(($a % $b) + $b) % $b", MUL
    end
    if f === Base.literal_pow
        p = literal(sc, args[3])
        p isa Val || throw(ArgumentError("unsupported power (statement $i)"))
        e = typeof(p).parameters[1]
        unit = T === Float32 ? "1.0f" : floating ? "1.0" : "1"
        e == 0 && return unit, PRIMARY
        e == 1 && return expression(sc, args[2])
        floating || e > 0 || throw(ArgumentError("a negative power of an integer is a DomainError in Julia (statement $i)"))
        x = operand(sc, args[2], MUL)
        # Squares, cubes and the reciprocal are written out; anything else is
        # `powi(x, n)`, by squaring (`powhelper!`).
        e == 2 && return "$x * $x", MUL
        e == 3 && return "$x * $x * $x", MUL
        e == -1 && return "$unit / $x", MUL
        return "$(powhelper!(sc.helpers, T))($(expression(sc, args[2])[1]), $e)", PRIMARY
    end
    # `@fastmath x^2` arrives as `pow_fast(x, Val(2))`: the literal power it was written as.
    f === Base.:^ && n == 2 && literal(sc, args[2]) isa Val && return rendered(sc, i, Expr(:call, Base.literal_pow, Base.:^, args[1], args[2]))
    if f === Base.:^
        floating || cplx || throw(ArgumentError("integer ^ with a non-literal exponent is not supported (statement $i)"))
        return fn("pow")
    end

    # Structs and tuples: field reads, and `==` field by field.
    if f in (Base.getproperty, Core.getfield, Base.getindex) && n == 2 && !isarray(valuetype(sc, args[1])) && (isstruct(valuetype(sc, args[1])) || istuple(valuetype(sc, args[1])))
        return (isindexediterate(sc, args[1]) ? value(sc, args[1]) : fieldaccess(sc, args[1], args[2])), PRIMARY
    end
    if f === Base.:(==) && n == 2 && (isstruct(valuetype(sc, args[1])) || istuple(valuetype(sc, args[1])))
        S = valuetype(sc, args[1])
        a, b = value(sc, args[1]), value(sc, args[2])
        names = fieldcnames(S)
        return join(("$a$(arrow(S))$c == $b$(arrow(S))$c" for c in names), " && "), LAND
    end

    # Comparison and logic.
    f in (Base.:<, Base.:<=, Base.:>, Base.:>=, Base.:(==), Base.:!=) && all(a -> valuetype(sc, a) <: Integer, args) && signedness("a comparison")
    f === Base.:<  && return op("<", REL)
    f === Base.:<= && return op("<=", REL)
    f === Base.:>  && return op(">", REL)
    f === Base.:>= && return op(">=", REL)
    f === Base.:(==) && return op("==", EQ)
    f === Base.:!= && return op("!=", EQ)
    f === Base.:(===) && return op("==", EQ)
    f === Base.:! && return unary("!")
    f === Base.not_int && return unary("!")
    f === Base.:& && return op("&", BAND)
    f === Base.:| && return op("|", BOR)
    f === Base.xor && return op("^", BXOR)
    f === Base.:<< && return op("<<", SHIFT)
    f === Base.:>> && return op(">>", SHIFT)
    f === Base.:~ && return unary(valuetype(sc, args[1]) === Bool ? "!" : "~")      # C's `~true` is -2, which is true

    # Math.
    if floating || cplx
        f === Base.abs   && return fn("fabs")
        f === Base.max   && return folded("fmax")
        f === Base.min   && return folded("fmin")
        f === Base.round && n == 1 && return fn("rint")            # Julia rounds to even; so does rint
        f === Base.atan  && n == 2 && return fn("atan2")
        for (g, name) in ((Base.sqrt, "sqrt"), (Base.cbrt, "cbrt"), (Base.sin, "sin"), (Base.cos, "cos"), (Base.tan, "tan"),
                          (Base.asin, "asin"), (Base.acos, "acos"), (Base.atan, "atan"), (Base.sinh, "sinh"),
                          (Base.cosh, "cosh"), (Base.tanh, "tanh"), (Base.exp, "exp"), (Base.exp2, "exp2"),
                          (Base.expm1, "expm1"), (Base.log, "log"), (Base.log2, "log2"), (Base.log10, "log10"),
                          (Base.log1p, "log1p"), (Base.floor, "floor"), (Base.ceil, "ceil"), (Base.trunc, "trunc"),
                          (Base.hypot, "hypot"), (Base.copysign, "copysign"))
            f === g && n == length(args) && !(args[1] isa Type) && return fn(name)
        end
    elseif T <: Integer
        f === Base.abs && T <: Unsigned && return expression(sc, args[1])        # nothing to do
        f === Base.abs && return T === Int64 ? fn("llabs", "stdlib.h") : T === Int32 ? fn("abs", "stdlib.h") :
                                 (push!(sc.headers, "stdlib.h"); ("($(ctype(T)))abs($(expression(sc, args[1])[1]))", UNARY))
        if f === Base.max || f === Base.min
            signedness("`$(nameof(f))`")
            acc = expression(sc, args[1])[1]
            for b in args[2:end]              # `max(a, b, c)` is `max(max(a, b), c)`
                b = expression(sc, b)[1]
                acc = "($acc $(f === Base.max ? ">" : "<") $b ? $acc : $b)"
            end
            return acc, PRIMARY
        end
        # `round(Int, x)`, `floor(Int, x)`, …: a math function then a cast.
        if f in (Base.round, Base.floor, Base.ceil, Base.trunc) && n == 2
            g = f === Base.round ? "rint" : f === Base.floor ? "floor" : f === Base.ceil ? "ceil" : "trunc"
            push!(sc.headers, "math.h")
            return "($(ctype(T)))$g($(expression(sc, args[2])[1]))", UNARY
        end
    end

    # `(x * 2.0)::Float64` is `x * 2.0`: the assertion holds, or Julia would have thrown. And
    # `convert(Float64, n)`, which a declared type puts in (`x::Float64 = 1`, `f(n)::Float64`),
    # is the cast: where the value doesn't fit the type exactly, Julia throws.
    f === Core.typeassert && n == 2 && T <: Number && return expression(sc, args[1])
    if f === Base.convert && n == 2 && T <: Number && literal(sc, args[1]) isa Type
        valuetype(sc, args[2]) === T && return expression(sc, args[2])
        return "($(ctype(T)))" * truth(args[2], UNARY), UNARY
    end
    # One C expression of its arguments: a row of the table (`idiom.jl`).
    r = idiom(f, T, [widen(valuetype(sc, a)) for a in args])
    r === nothing || return written(sc, r, T, args)

    # Classification of a floating value: the same names, from math.h.
    # They are macros that take any floating type: no `f` forms.
    f in (Base.isnan, Base.isinf, Base.isfinite, Base.signbit) && n == 1 &&
        return (push!(sc.headers, "math.h"); ("$(nameof(f))($(expression(sc, args[1])[1]))", PRIMARY))

    # The limits of a type: the macros C names them by.
    if f in (Base.typemax, Base.typemin, Base.floatmax, Base.floatmin, Base.eps) && (n == 0 || literal(sc, args[1]) isa Type)
        S = n == 0 ? Float64 : literal(sc, args[1])
        S in (Float64, Float32) && f === Base.eps && (push!(sc.headers, "float.h"); return (S === Float64 ? "DBL_EPSILON" : "FLT_EPSILON"), PRIMARY)
        S in (Float64, Float32) && f === Base.floatmax && (push!(sc.headers, "float.h"); return (S === Float64 ? "DBL_MAX" : "FLT_MAX"), PRIMARY)
        S in (Float64, Float32) && f === Base.floatmin && (push!(sc.headers, "float.h"); return (S === Float64 ? "DBL_MIN" : "FLT_MIN"), PRIMARY)
        S in (Float64, Float32) && f === Base.typemax && (push!(sc.headers, "math.h"); return "INFINITY", PRIMARY)
        S in (Float64, Float32) && f === Base.typemin && (push!(sc.headers, "math.h"); return "-INFINITY", UNARY)
        S === Bool && return value(sc, f === Base.typemax), PRIMARY
        if S <: Integer && f in (Base.typemax, Base.typemin)
            bits = 8 * sizeof(S)
            S <: Unsigned && return (f === Base.typemax ? "UINT$(bits)_MAX" : "0"), PRIMARY
            return (f === Base.typemax ? "INT$(bits)_MAX" : "INT$(bits)_MIN"), PRIMARY
        end
    end

    # Conversions: a call to a type.
    f isa Type && isstruct(T) && return compound(sc, T, args), PRIMARY
    f isa Type && n == 1 && return "($(ctype(T)))" * truth(args[1], UNARY), UNARY

    # Arrays, as scalars: an element, or a size.
    f === Base.getindex && return index(sc, args[1], args[2:end]), PRIMARY
    f === Base.length && return string(prod(shape(valuetype(sc, args[1])))), PRIMARY
    f === Base.size && n == 2 && !(literal(sc, args[2]) isa Integer) &&
        throw(ArgumentError("`size(A, d)` with a `d` that isn't a literal: the sizes are known when transpiled, so say which, `size(A, 1)` (statement $i)"))
    f === Base.size && n == 2 && return string(shape(valuetype(sc, args[1]))[literal(sc, args[2])]), PRIMARY

    # One of the user's own functions.
    name = usercall!(sc, f, args)
    name === nothing || return "$name($(callargs(sc, args)))", PRIMARY


    unknown(sc, f, args, i)
end

# The refusal of last resort: a call nothing above knew. It names the call as Julia sees it,
# with the types of its arguments, since the same function is often known for others.
function unknown(sc::Scope, f, args, i)
    (f === Colon() || f === Base.range || f === Base.OneTo) &&
        throw(ArgumentError("a range kept in a variable has no C: ranges are supported as the range of a `for` and as an index, `v[2:4]`. Write the range in the `for` itself (statement $i)"))
    f in (Base.sincos, Base.minmax) &&
        throw(ArgumentError("`$(nameof(f))` is only available destructured, `s, c = sincos(x)`, `lo, hi = minmax(a, b)`: C has no pair to keep in a variable (statement $i)"))
    types = join(("::" * replace(string(widen(valuetype(sc, a))), "StaticArraysCore." => "") for a in args), ", ")
    throw(ArgumentError("`$(f isa Function ? nameof(f) : f)($types)` has no C yet: the transpiler doesn't know this function for these arguments. Write it with what it does know, or as a function of your own (statement $i)"))
end

# An operation along one dimension of an array, into `dest`: a reduction that keeps the
# dimension at extent 1 (`sum(A; dims=1)` of a 2×3 is 1×3), `diff` (the dimension
# shrinks by one), `cumsum` and `cumprod` (the shape stays). The dimension comes from
# the `dims` keyword, or is 1 for a vector; the helper is `sum1_2x3`, `diff2_2x3`,
# `cumsum_4` (`dimhelper!`).
function along!(lines, sc::Scope, i, f, args, kw, dest; declaration::Bool=false)
    op = f === Base.sum ? :sum : f === Base.prod ? :prod : f === Base.maximum ? :maximum : f === Base.minimum ? :minimum :
         f === Base.diff ? :diff : f === Base.cumsum ? :cumsum : f === Base.cumprod ? :cumprod :
         throw(ArgumentError("unsupported operation along a dimension: $f (statement $i)"))
    length(args) == 1 && isarray(valuetype(sc, args[1])) || throw(ArgumentError("$f along a dimension takes one array (statement $i)"))
    T = valuetype(sc, args[1])
    keys(kw) ⊆ (:dims,) || throw(ArgumentError("unsupported keywords for $f: $(join(setdiff(keys(kw), (:dims,)), ", ")) (statement $i)"))
    d = haskey(kw, :dims) ? kw.dims : ndims(T) == 1 ? 1 : throw(ArgumentError("$f of a $(describe(T)) needs dims (statement $i)"))
    d isa Integer && 1 <= d <= ndims(T) || throw(ArgumentError("dims=$d is out of range for a $(describe(T)) (statement $i)"))
    R = widen(sc.ci.ssavaluetypes[i])
    shape(R) === nothing && throw(ArgumentError("the size of $f along dimension $d isn't known (statement $i)"))
    name = dimhelper!(sc.helpers, op, d, T, R)
    declaration && emit!(lines, sc, declare(R, dest) * ";")
    emit!(lines, sc, "$name($(value(sc, args[1])), $dest);")
    step!(lines, sc, "$dest = $op($(value(sc, args[1]))$(ndims(T) == 1 ? "" : "; dims=$d"))")
    sc.shapes[i] = R
end

# `fill!(A, x)`, `A .= 0`, `A .= x`, `A .= B .* 2`: written into the existing array.
function inplace!(lines, sc::Scope, i, st::Expr)
    f = callee(sc.ci, st.args[1])
    dest, D = value(sc, st.args[2]), valuetype(sc, st.args[2])
    isarray(D) || throw(ArgumentError("$f into a $D (statement $i)"))
    x = st.args[3]
    if f === Base.materialize!
        node = sc.ci.code[x.id]                   # broadcasted(g, args...)
        if callee(sc.ci, node.args[2]) === Base.identity && length(node.args) == 3 && !isarray(valuetype(sc, node.args[3]))
            x = node.args[3]                      # `A .= x`: a fill
        else
            return broadcast!(lines, sc, i, x, dest)
        end
    end
    start = length(lines) + 1
    literal(sc, x) == 0 ? zero!(lines, sc, dest, D) : fill!(lines, sc, dest, D, value(sc, eltype(D) <: AbstractFloat && x isa Integer ? eltype(D)(x) : x))
    step!(lines, sc, "$dest .= $(value(sc, x))"; from=start)
end

# `A + λI`, `A - λI`, `λI - A`: the matrix with λ on its diagonal added or subtracted,
# through `addI_3x3(A, λ, out)` and friends (`scalinghelper!`).
function scaling!(lines, sc::Scope, i, op, args, dest; declaration::Bool=false)
    k = findfirst(a -> literal(sc, a) isa LinearAlgebra.UniformScaling, args)
    λ = literal(sc, args[k]).λ
    A = args[3 - k]
    T = valuetype(sc, A)
    isarray(T) && ndims(T) == 2 && allequal(shape(T)) || throw(ArgumentError("I can only be added to a square matrix, not a $(describe(T)) (statement $i)"))
    R = widen(sc.ci.ssavaluetypes[i])
    shape(R) === nothing && (R = T)
    E = eltype(R)
    lam = value(sc, E <: AbstractFloat ? E(λ) : λ)
    mode = op == :add ? :addI : k == 2 ? :subI : :rsubI
    declaration && emit!(lines, sc, declare(R, dest) * ";")
    emit!(lines, sc, "$(scalinghelper!(sc.helpers, mode, T, R))($(value(sc, A)), $lam, $dest);")
    step!(lines, sc, "$dest = " * (mode == :rsubI ? "$(lam)I - $(value(sc, A))" : "$(value(sc, A)) $(op == :add ? "+" : "-") $(lam)I"))
    sc.shapes[i] = R
end

# ---- structs and tuples -------------------------------------------------------------

# The module that owns a global's binding: `Inf` read in a module that imports it is
# `Base.Inf`; a user's `g` is theirs wherever it was read.
owner(x::GlobalRef) = Base.binding_module(x.mod, x.name)

# Is this global Julia's own — a function, a type, a module, `pi`, `Inf` — rather than a
# value of the user's?
builtin(x::GlobalRef, v) = v isa Function || v isa Type || v isa Module || v isa AbstractIrrational || nameof(Base.moduleroot(owner(x))) in known

# The type of a global's value as the transpiler sees types: a regular array carries
# its size, as a sized argument does.
globaltype(v) = v isa AbstractArray && shape(normalize(typeof(v))) === nothing ? shaped(eltype(v), size(v)) : normalize(typeof(v))

"""
    claim!(prog, key, preferred, julia, [second]) -> name

The file-scope C name for one of the author's own things — a function, a global — asked
for in one place, so that every kind keeps clear of every other: the names already
claimed, struct and tuple typedefs, helpers, foreign wrappers, the macros, C's own words,
and anything shaped like a helper's name (`ishelpername`). `second` is a function's name
with its types, tried before `_`. What was asked for and what was given is kept, for
`audit` to see whether the order things were met in gave a name to the wrong one.
"""
function claim!(prog::Program, key, preferred, julia, second=nothing)
    # A macro of ours is not in the way: it ranks below the author's names and is the one to
    # give way, which `audit` arranges.
    free_(n) = !(n in reserved) && (!(n in filescope(prog)) || haskey(irrationals, n)) && !(n in prog.avoid) &&
               !(n in Base.values(prog.fixed)) && !ishelpername(n)
    name = if haskey(prog.fixed, key)
        prog.fixed[key]
    elseif free_(preferred)
        preferred
    elseif second !== nothing && free_(second)
        second
    else
        n = preferred * "_"
        while !free_(n); n *= "_"; end
        n
    end
    push!(prog.names, name)
    push!(prog.claims, (; key, preferred, julia=String(julia), name))
    return name
end

# A global variable of the program, registered once per binding (or per name, for a
# value with no binding): `g` in `const g = 9.81` is `const double g = 9.81;`. Named
# like anything else, with `_` on a collision.
function global!(prog::Program, mod::Union{Module, Nothing}, name::Symbol, value; constant::Union{Bool, Nothing}=nothing)
    for g in prog.globals
        (g.mod === mod && g.name === name) && return g
    end
    T = globaltype(value)
    (isstruct(T) && ismutabletype(T)) && throw(ArgumentError("the global $name is a mutable struct; the C caller owns those"))
    structdef!(prog, T)
    isconst = constant !== nothing ? constant : mod !== nothing ? Base.isconst(mod, name) : true
    cname = claim!(prog, (mod, name), mod === nothing ? identifier(string(name)) : qualified(string(name), mod), string(name))
    g = Global(cname, mod, name, value, isconst)
    push!(prog.globals, g)
    return g
end

# A global's declaration: with its value, `const double v[3] = {1.0, 2.0, 3.0};`, or
# without, for the header's `extern`.
function globaldecl(g::Global; value::Bool=true, note=nothing, text=nothing)
    T = globaltype(g.value)
    decl = (g.constant && !(T <: AbstractString) ? "const " : "") * declare(T, g.cname) * (value ? " = " * something(text, initializer(g.value)) : "") * ";"
    note === nothing && return decl
    nl = findfirst('\n', decl)                  # a matrix's rows are lines of their own: the note stays on the first
    return nl === nothing ? decl * "  // " * note : decl[1:nl-1] * "  // " * note * decl[nl:end]
end

# The Julia expression a global was assigned, as its C initializer, so that `π` in the
# Julia is `LEGIBLEC_PI` in the C rather than the double it became — the symbol says so,
# never a value. Only what a static initializer may hold: number literals, an irrational
# by its symbol (`π`, `ℯ`, the author's own), a sign, and `+ - * /` of those; an array literal of such, laid
# out by evaluating the literal with each leaf replaced by its number. A leaf that is
# anything else — a name, a call — has only its value, written as digits. Every rendered
# leaf is checked against the value Julia holds; any disagreement, and the whole value
# is written instead, so a line that isn't the assignment behind the value can do no harm.
function symbolic(g::Global, text)
    ex = try Meta.parse(text) catch; return nothing end
    rhs = assigned(ex, g.name)
    rhs === nothing && return nothing
    v = g.value
    v isa AbstractArray || return leafsymbolic(rhs, g.mod, v)
    rhs isa Expr && rhs.head in (:vect, :vcat, :hcat, :hvcat, :ncat, :typed_vcat, :typed_hcat, :typed_hvcat, :typed_ncat) || return nothing
    leaves = Any[]
    marked = marklayout(rhs, leaves)
    layout = try Core.eval(g.mod, marked) catch; return nothing end
    layout isa AbstractArray && all(x -> x isa Real && isinteger(x), layout) || return nothing
    size(layout) == size(v) || return false                  # a literal of another shape: not the line this value came from
    grid = Array{String}(undef, size(v))
    for k in eachindex(v)
        s = leafsymbolic(leaves[Int(layout[k])], g.mod, v[k])
        s === false && return false
        grid[k] = something(s, initializer(v[k]))
    end
    return braces(grid)
end

# The literal with each leaf replaced by its number in `leaves`; the dimension of an
# `ncat`, the row lengths of an `hvcat` and the type of a `typed_` form stay.
function marklayout(ex, leaves)
    ex isa Expr && ex.head in (:vect, :vcat, :hcat, :hvcat, :ncat, :nrow, :row, :typed_vcat, :typed_hcat, :typed_hvcat, :typed_ncat) || (push!(leaves, ex); return length(leaves))
    keep = ex.head in (:ncat, :nrow, :typed_ncat) ? 1 : ex.head in (:hvcat, :typed_vcat, :typed_hcat) ? 1 : 0
    ex.head in (:typed_ncat, :typed_hvcat) && (keep = 2)
    return Expr(ex.head, ex.args[1:keep]..., (marklayout(a, leaves) for a in ex.args[keep+1:end])...)
end

# One leaf as C, or nothing for a leaf with only a value, or false when the leaf's own
# value disagrees with the one Julia holds.
function leafsymbolic(ex, mod, expected)
    r = crender(ex, mod)
    r === nothing && return nothing
    actual = try Core.eval(mod, ex) catch; return false end
    actual isa Number && expected isa Number || return false
    ok = try isequal(convert(typeof(expected), actual), expected) catch; false end
    return ok ? r[1] : false
end

# A scalar expression a static initializer may hold, as C text with its precedence.
function crender(ex, mod)
    ex isa Bool && return (initializer(ex), PRIMARY)
    ex isa Integer && return (integer(ex), PRIMARY)
    ex isa AbstractFloat && return (initializer(ex), PRIMARY)
    if ex isa Symbol
        isdefined(mod, ex) || return nothing
        v = getfield(mod, ex)
        v isa AbstractIrrational && return (macroname(v), PRIMARY)
        return nothing
    end
    ex isa Expr && ex.head === :call || return nothing
    op = ex.args[1]
    if op === :- && length(ex.args) == 2
        r = crender(ex.args[2], mod)
        r === nothing && return nothing
        return ("-" * (r[2] < UNARY ? "(" * r[1] * ")" : r[1]), UNARY)
    end
    op in (:+, :-, :*, :/) && length(ex.args) >= 3 || return nothing
    prec = op in (:+, :-) ? ADD : MUL
    parts = String[]
    for (k, a) in enumerate(ex.args[2:end])
        r = crender(a, mod)
        r === nothing && return nothing
        # The right operand of `-` or `/` needs parentheses at equal precedence too.
        need = r[2] < prec || (k > 1 && op in (:-, :/) && r[2] == prec)
        push!(parts, need ? "(" * r[1] * ")" : r[1])
    end
    return (join(parts, " $op "), prec)
end

# The right-hand side assigned to `name` in a parsed line: `x = …`, `const x = …`,
# `x::T = …`, inside a one-line module or several statements too.
function assigned(ex, name::Symbol)
    ex isa Expr || return nothing
    if ex.head === :(=)
        lhs = ex.args[1]
        lhs isa Expr && lhs.head === :(::) && (lhs = lhs.args[1])
        lhs === name && return ex.args[2]
    end
    for a in ex.args
        r = assigned(a, name)
        r === nothing || return r
    end
    return nothing
end

# Where a global was assigned, for its comment: the file, the line, the Julia line's text
# and its trailing `# note`. Julia keeps no location for a binding, so the source is
# searched: the module's own file from its first line, for a module with one, then the
# files the program's functions came from, where the last top-level `name = …` is the
# one whose value the transpiler saw.
function globalsource(g::Global, files)
    found = Any[]
    g.mod isa Module || return found
    pat = Regex("(^|;)\\s*(const\\s+)?\\Q$(g.name)\\E\\s*(::[^=]*)?=[^=]")
    function candidates!(path, order)
        lines = readlines(path)
        for k in order(lines)
            occursin(pat, lines[k]) || continue
            note = split_comment(lines[k])[2]
            push!(found, (file=basename(path), line=k, text=strip(lines[k]), note=note === nothing || isempty(strip(note)) ? nothing : strip(note)))
        end
    end
    # Every line that could be the one, likeliest first: in the module's own file from the
    # module's first line on; then in the files the functions came from, last assignment
    # first. Which of them it is, `globallines` tells by the value.
    if isdefined(Base, :moduleloc)
        loc = Base.moduleloc(g.mod)
        path = isempty(string(loc.file)) ? nothing : Base.find_source_file(string(loc.file))
        path !== nothing && isfile(path) && candidates!(path, lines -> max(loc.line, 1):length(lines))
    end
    for f in unique(files)
        path = Base.find_source_file(string(f))
        path !== nothing && isfile(path) && candidates!(path, lines -> length(lines):-1:1)
    end
    return unique(found)
end

# A Julia value as a C initializer: numbers, characters, strings, arrays in row-major
# nesting, tuples and structs field by field.
initializer(x::Bool) = booltype[] === Bool ? (x ? "true" : "false") : (x ? "1" : "0")
initializer(x::Integer) = integer(x)
initializer(x::AbstractFloat) = isinf(x) ? (x > 0 ? "INFINITY" : "-INFINITY") : isnan(x) ? "NAN" : x isa Float32 ? replace(string(x), "f" => "e") * "f" : repr(Float64(x))
initializer(x::AbstractIrrational) = macroname(x)   # `const τ = π` keeps the name; a stored double is digits
initializer(x::Char) = charliteral(x)
initializer(x::AbstractString) = "\"" * cstring(x) * "\""
initializer(x::Union{LinearAlgebra.Adjoint{<:Any, <:AbstractVector}, LinearAlgebra.Transpose{<:Any, <:AbstractVector}}) = initializer(parent(x))
initializer(x::AbstractArray) = braces(map(initializer, x))

# The braces of an array initializer from the text of each element: a vector on one
# line, a matrix one row per line, higher dimensions nested a level of indentation each.
function braces(x::AbstractArray{String}, depth::Integer=0)
    ndims(x) == 1 && return "{" * join(x, ", ") * "}"
    rows = ["    "^(depth + 1) * braces(selectdim(x, 1, i), depth + 1) * "," for i in 1:size(x, 1)]
    return "{\n" * join(rows, "\n") * "\n" * "    "^depth * "}"
end

# `double A[2][2] = {…};`: an array declared with its initializer, a line per row.
function initialize!(lines, sc::Scope, decl, grid::AbstractArray{String})
    for l in split(decl * " = " * braces(grid) * ";", '\n')
        emit!(lines, sc, l)
    end
end
initializer(x::Tuple) = "{" * join(initializer.(x), ", ") * "}"
initializer(x) = "{" * join((initializer(getfield(x, k)) for k in 1:fieldcount(typeof(x))), ", ") * "}"

# The typedef for a struct or tuple type, added to the program once, after the types
# of its fields. Anything that isn't a struct or tuple is ignored.
function structdef!(prog::Program, T::Type)
    (isstruct(T) || istuple(T)) || return
    any(p -> p.first === T, prog.structs) && return
    fields = istuple(T) ? collect(T.parameters) : [fieldtype(T, k) for k in 1:fieldcount(T)]
    for F in fields
        structdef!(prog, F)
    end
    lines = ["    " * declare(F, c) * ";" for (F, c) in zip(fields, fieldcnames(T))]
    doc = istuple(T) ? "/// a tuple held as one value: $(join(fieldcnames(T), ", "))\n" : ""
    push!(prog.structs, T => doc * "typedef struct {\n" * join(lines, "\n") * "\n} $(structname(T));\n")
end

# `p.x`, `c->n`, `t.a`: field `f` (a symbol, or a 1-based position) of the struct or
# tuple value `x`.
function fieldaccess(sc::Scope, x, f)
    S = valuetype(sc, x)
    f = literal(sc, f)
    f isa QuoteNode && (f = f.value)
    x isa Core.SSAValue && haskey(sc.pair, x.id) && return sc.pair[x.id][f]   # `sincos`: sin or cos
    k = tuplekind(sc, x)
    k !== nothing && return isempty(k.cname) ? k.fields[f] : value(sc, x) * "." * k.fields[f]
    return value(sc, x) * arrow(S) * fieldcname(S, f)
end

# Is `x` the result of `indexed_iterate` — a field read in disguise?
isindexediterate(sc::Scope, x) = x isa Core.SSAValue && iscall(sc.ci.code[x.id], Base.indexed_iterate)

# A struct or tuple of type `T` from its field values, as one expression:
# `(Point){x, y}`. Only when no field is an array (C can't initialize an array member
# from another array).
function compound(sc::Scope, T::Type, args)
    isstruct(T) && ismutabletype(T) && throw(ArgumentError("creating a mutable struct ($T) inside transpiled code is not supported; the C caller owns those"))
    structdef!(sc.prog, T)
    any(a -> isarray(valuetype(sc, a)), args) && throw(ArgumentError("a $T holding an array can't be built in an expression"))
    return "($(ctype(T))){$(join((value(sc, a) for a in args), ", "))}"
end

# Build a struct or tuple of type `T` in `dest` (already declared if `declared`): one
# compound literal when every field is a scalar, otherwise field by field with arrays
# copied in.
function compound!(lines, sc::Scope, i, T::Type, args, dest; declared::Bool)
    isstruct(T) && ismutabletype(T) && throw(ArgumentError("creating a mutable struct ($T) inside transpiled code is not supported; the C caller owns those"))
    structdef!(sc.prog, T)
    if !any(a -> isarray(valuetype(sc, a)), args)
        emit!(lines, sc, (declared ? "" : "$(ctype(T)) ") * "$dest = $(compound(sc, T, args));")
        return
    end
    # `b = Bag(s * axis, vsum(b))`: an argument reads the variable being built, and Julia
    # evaluated every argument before building — so the struct is built beside it and
    # assigned whole, never field by field over what an argument still has to read.
    if any(a -> touches(sc, a, dest), args)
        beside = temp!(sc, nothing, [dest])
        compound!(lines, sc, i, T, args, beside; declared=false)
        emit!(lines, sc, (declared ? "" : "$(ctype(T)) ") * "$dest = $beside;")
        return
    end
    start = length(lines) + 1
    declared || emit!(lines, sc, "$(ctype(T)) $dest;")
    fields = istuple(T) ? collect(T.parameters) : [fieldtype(T, k) for k in 1:fieldcount(T)]
    copied = false
    for (F, c, a) in zip(fields, fieldcnames(T), args)
        value(sc, a) == "$dest.$c" && continue          # computed into its place (`placement`)
        isarray(F) ? (copy!(lines, sc, value(sc, a), valuetype(sc, a), "$dest.$c", F); copied = true) :
                     emit!(lines, sc, "$dest.$c = $(value(sc, a));")
    end
    # Built over several lines, the construction is a step of its line like any other;
    # with every array computed into its place, what's left is scalar stores, no step.
    istuple(T) || !copied || step!(lines, sc, "$dest = $(ctype(T))($(join([value(sc, a) for a in args], ", ")))"; from=start)
end

# Is the tuple made at statement `i` used only by constructors and block
# constructions (or by nothing), so that it never needs to exist in C?
function consumed(ci, i)
    for st in ci.code
        uses(st, i) || continue
        st isa Expr && st.head === :(=) && (st = st.args[2])          # `X = [A B; C D]`
        st isa Expr && st.head === :call || return false
        f = callee_or_nothing(ci, st.args[1])
        (f !== nothing && (isconstruction(f) || f === Base.materialize)) || return false
    end
    return true
end

# ---- step comments ------------------------------------------------------------------

# Record that the C just emitted — everything from line `from` to the last line —
# computes `text`, one step of the current Julia line, in the spelling the helper
# comments use and with the C names: `temp2_A_b_c = temp1_A_b \\ c`. `steps!` turns
# these into comments once the function is built.
function step!(lines, sc::Scope, text; from::Int=length(lines))
    from <= length(lines) || return                 # a step that emitted nothing: nothing to comment
    push!(sc.steps, (from, length(lines), text, sc.stmtline[sc.current]))
end

# The Julia spelling of an operator on structs, for the step comment: `q * p * q'`,
# `conj(q)`. An operand that is itself an operator call written in place is spelled the
# same way, in parentheses when its operator is another.
function julian(sc::Scope, f, args)
    sym = nameof(f)
    function part(a)
        a isa Core.SSAValue && a.id in sc.inlined || return value(sc, a)
        st = sc.ci.code[a.id]
        g = st isa Expr && st.head === :call ? callee_or_nothing(sc.ci, st.args[1]) : nothing
        g isa Function && any(x -> isstruct(valuetype(sc, x)), st.args[2:end]) || return value(sc, a)
        inner = julian(sc, g, st.args[2:end])
        length(st.args) > 2 && nameof(g) !== sym ? "($inner)" : inner
    end
    parts = map(part, args)
    sym === :adjoint && return parts[1] * "'"
    length(parts) >= 2 && haskey(operators, sym) && sym !== :! && return join(parts, " $sym ")
    length(parts) == 1 && sym in (:-, :!) && return "$sym$(parts[1])"
    return "$sym($(join(parts, ", ")))"
end

# A value's name in a step comment: `Aᵀ` when it's transposed, `Aᴴ` when its elements are
# read conjugated too, the adjoint of a complex array. Names say `T` and `H` the same way.
spell(T::Type, name::AbstractString) = istransposed(T) ? name * tmark(T) : name
tmark(T::Type) = isconjugated(T) ? "ᴴ" : "ᵀ"

# Write the step comments in. On a Julia line that became more than one step, each
# step gets its text — at the end of the line when the step is one statement, on the
# line above when it's a loop or several — so a reader can follow the temps. A line
# that became a single step already has its source comment and needs no more.
function steps!(lines, sc::Scope)
    isempty(sc.steps) && return
    counts = Dict{Int, Int}()
    for (_, _, _, l) in sc.steps
        counts[l] = get(counts, l, 0) + 1
    end
    chosen = [s for s in sc.steps if counts[s[4]] >= 2]
    empty!(sc.steps)
    for (from, at, text, _) in chosen
        if from == at
            lines[at] *= "  // " * text
        else
            indent = lines[from][1:findfirst(!isspace, lines[from])-1]
            push!(sc.inserts, (from, 2, indent * "// " * text))
        end
    end
end

# Whether `x = f(...)` with `x` among the operands can write straight into `x`: yes
# for anything elementwise — `+`, `-`, a scalar multiple or quotient, a broadcast —
# when every operand that is `x` lines up with the result element for element, since
# each output element then depends only on the same elements of the inputs. A product,
# a solve, an inverse, a cross product, a transposed operand or a construction reads
# elements the output has already overwritten, so those go through a temp.
function inplace(sc::Scope, rhs::Expr, R::Type)
    f = callee_or_nothing(sc.ci, rhs.args[1])
    args = rhs.args[2:end]
    if f === Base.materialize
        b = sc.ci.code[args[1].id]
        b isa Expr && b.head === :call && callee_or_nothing(sc.ci, b.args[1]) === Base.broadcasted || return false
        args = b.args[3:end]
    elseif f === Base.:*
        count(a -> isarray(valuetype(sc, a)), args) == 1 || return false
    elseif f === Base.:/
        isarray(valuetype(sc, args[2])) && return false
    elseif !(f in (Base.:+, Base.:-))
        return false
    end
    return all(a -> !isarray(valuetype(sc, a)) || axis(valuetype(sc, a)) == axis(R) && shape(valuetype(sc, a)) == shape(R), args)
end

# ---- calls to other functions -------------------------------------------------------

# A call to one of the user's own functions, at these arguments: its C name, after
# registering the callee's concrete instance to be transpiled if it isn't already. A
# function is the user's if it isn't from Julia itself or the packages the transpiler
# understands. Nothing for anything else.
usercall!(sc::Scope, f, args) = (r = userinstance!(sc, f, args); r === nothing ? nothing : r[3])

# The instance, signature, and C name behind a call to a user function, or nothing.
function userinstance!(sc::Scope, f, args)
    f isa Function || return nothing
    spec = Any[]
    for a in args
        T = valuetype(sc, a)
        T <: Shaped && (push!(spec, eltype(T)); append!(spec, shape(T)); continue)
        push!(spec, juliatype(T))
    end
    samedispatch(sc, f, args, spec)
    return register!(sc.prog, f, spec)
end

# A variable the one-type rule widened (`onetype!`) is an `Int64` on one path and a
# `Float64` on another in Julia, and a `double` on both in C. That is harmless where the
# value is the same number either way, and not where Julia would pick a *method* by the
# path's type: then the C would always call the one method. So a widened argument may
# reach only a function whose dispatch doesn't depend on which member it is.
function samedispatch(sc::Scope, f, args, spec)
    ci = sc.ci
    # Julia's own function on Julia's own types is never a function of the user's (`register!`).
    nameof(Base.moduleroot(parentmodule(f))) in known && !any(T -> T isa Type && isstruct(T), spec) && return
    for (k, a) in enumerate(args)
        s = slotof(sc, a)
        s === nothing && continue
        T = ci.slottypes[s]
        T isa Union || continue
        members = Base.uniontypes(T)
        # Julia's own methods differ by type too — `Int * Float64` and `Float64 * Float64` —
        # but they are the same arithmetic, spelled by one C operator; only a method of the
        # user's becomes a different C function.
        try
            picks = [Base.which(f, Tuple(Any[j == k ? M : (S isa Type ? S : typeof(S)) for (j, S) in enumerate(spec)])) for M in members]
            (allequal(picks) || all(m -> nameof(Base.moduleroot(m.module)) in known, picks)) && continue
        catch
        end
        throw(ArgumentError("`$(ci.slotnames[s])` is a $(join(members, " on one path and a ")) on another, and which method of `$(nameof(f))` runs depends on which; C holds it as one type, so give the variable one type (`$(ci.slotnames[s]) = 0.0`, say)"))
    end
end

# The instance, signature and C name of user function `f` at the argument spec (types,
# with a regular array as element type and sizes), registering it to be transpiled if
# it isn't already. Nothing if it isn't the user's or can't be resolved.
function register!(prog::Program, f, spec)
    # Julia's own function on Julia's own types is Julia's; on a struct of the user's it
    # may be the user's method (`Base.:*(a::Quaternion, b::Quaternion)`), so look.
    nameof(Base.moduleroot(parentmodule(f))) in known &&
        !any(T -> T isa Type && isstruct(T), spec) && return nothing
    mi, sig = try
        any(x -> x isa Integer, spec) ? resolve(f, spec) : (m = Base.method_instance(f, Tuple(spec)); m === nothing ? (nothing, nothing) : (m, argtypes(m)))
    catch e
        e isa ArgumentError ? (nothing, nothing) : rethrow()
    end
    mi === nothing && return nothing
    nameof(Base.moduleroot(mi.def.module)) in known && return nothing
    haskey(prog.calls, mi) && return (mi, sig, prog.calls[mi])
    base = qualified(operatorname(mi.def.name, sig), mi.def.module)
    typed = join([base; filter(!isempty, [describe(T, 2, alldouble(sig)) for T in sig])], "_")
    name = claim!(prog, mi, base, string(mi.def.name), typed)
    prog.calls[mi] = name
    push!(prog.pending, (mi, sig, name))
    return (mi, sig, name)
end

# What an instance returns, as the transpiler sees types.
# What an instance returns, as the transpiler sees types. A C function has one return
# type, so a union of numbers — `r > 0 ? r : 0` — settles to the one holding them all,
# the same numbers Julia returns; any other union — a number on one path and a string
# on another — is refused, naming the function and the line of each `return`, since
# no C signature can say it.
function returntype(mi::Core.MethodInstance)
    ci, R = only(Base.code_typed_by_type(mi.specTypes; optimize=false))
    R = widen(R)
    R isa Union || return R
    members = Base.uniontypes(R)
    all(M -> M isa DataType && M <: Number && isconcretetype(M), members) && return promote_type(members...)
    lines = statementlines(mi, length(ci.code))
    at = [(widen(valuetype_ir(ci, st.val)), lines[k]) for (k, st) in enumerate(ci.code) if st isa Core.ReturnNode && isdefined(st, :val)]
    spell(M) = isarray(M) && shape(M) !== nothing ? describe(M) : string(M)
    listed = join(("$(spell(M)) at line $l" for (M, l) in at), ", ")
    throw(ArgumentError("`$(mi.def.name)` returns values of different types from the same argument types ($listed); a C function has one return type, and no C signature can say this"))
end

# The Julia type behind a value the transpiler tracks: a row is an `Adjoint` of a
# static vector; an eagerly transposed matrix is the matrix Julia would have made.
function juliatype(T::Type)
    T <: Transposed || return T
    E, S = eltype(T), shape(T)
    ndims(T) == 1 && return LinearAlgebra.Adjoint{E, SVector{S[1], E}}
    return SMatrix{S[2], S[1], E, S[1] * S[2]}
end

# The C arguments of a call: values by name or literal. An eagerly transposed matrix
# would have to be materialized first, since the callee expects Julia's real matrix;
# until that's done, store it in a variable before the call.
function callargs(sc::Scope, args)
    out = String[]
    for a in args
        T = valuetype(sc, a)
        istransposed(T) && ndims(T) == 2 && throw(ArgumentError("passing a transposed matrix straight to a function is not supported yet; store it first (B = A')"))
        k = tuplekind(sc, a)
        if istuple(T) && k !== nothing
            # A tuple goes as its elements: the callee takes them as separate parameters.
            append!(out, isempty(k.cname) ? k.fields : [value(sc, a) * "." * c for c in k.fields])
        elseif istuple(T)
            append!(out, [value(sc, a) * "." * c for c in fieldcnames(T)])
        else
            push!(out, value(sc, a))
        end
    end
    return join(out, ", ")
end

# Does the IR value `a` refer to the C variable `x`, looking through the broadcast and
# tuple nodes a construction is built from?
function mentions(sc::Scope, x, a)
    if a isa Core.SSAValue && sc.ci.code[a.id] isa Expr && sc.ci.code[a.id].head === :call
        f = callee_or_nothing(sc.ci, sc.ci.code[a.id].args[1])
        (f === Base.broadcasted || f === Core.tuple) && return any(b -> mentions(sc, x, b), sc.ci.code[a.id].args[2:end])
    end
    v = try value(sc, a) catch; return false end
    return v == x || startswith(v, x * "[") || startswith(v, x * ".")   # the variable, or an element or field of it
end

# ---- ccall ---------------------------------------------------------------------------

# The C for a `ccall`: the symbol called with its arguments, plus a prototype for it
# (or the header it comes from) so the output stands alone. Julia that calls C becomes C
# that calls C.
function foreign!(sc::Scope, st::Expr)
    sym = st.args[1]
    sym isa QuoteNode && (sym = sym.value)
    sym isa Tuple && (sym = sym[1])
    sym isa Symbol || throw(ArgumentError("ccall to a computed function pointer is not supported"))
    name = string(sym)
    R, AT = st.args[2], collect(st.args[3])
    args = foreignargs(sc, st)
    cargs = String[]
    ptypes = String[]
    for (T, a) in zip(AT, args)
        if T <: Ptr
            # A pointer into an array. An immutable static array is passed as Julia
            # passes it, read-only; a mutable one may be written through, which
            # costs our own parameter its `const`.
            V = valuetype(sc, a)
            readonly = isarray(V) && !(V <: Shaped) && !ismutabletype(V)
            readonly || (a isa Core.SlotNumber && push!(sc.mutated, a.id))
            push!(ptypes, (readonly ? "const " : "") * ctype(T.parameters[1]) * " *")
            push!(cargs, isarray(V) ? (ndims(V) == 1 ? value(sc, a) : "&" * value(sc, a) * "[0]"^(ndims(V))) : "&" * value(sc, a))
        elseif T <: Ref
            push!(ptypes, ctype(T.parameters[1]) * " *")
            push!(cargs, "&" * value(sc, a))
        else
            push!(ptypes, ctype(T))
            push!(cargs, value(sc, a))
        end
    end
    header = foreignheader(name)
    if header === nothing
        proto = "$(ctype(R)) $name($(isempty(ptypes) ? "void" : join(ptypes, ", ")));"
        # Two calls that disagree on `const` for a pointer: the prototype takes the
        # weaker promise.
        old = get(sc.prog.foreign, name, proto)
        sc.prog.foreign[name] = old == proto ? proto : replace(proto, "const " => "")
    else
        push!(sc.headers, header)
    end
    return "$name($(join(cargs, ", ")))"
end

# The values a `ccall` passes, with Julia's `cconvert`/`unsafe_convert` wrapping undone.
function foreignargs(sc::Scope, st::Expr)
    n = length(st.args[3])
    function unwrap(a)
        a isa Core.SSAValue || return a
        x = sc.ci.code[a.id]
        x isa Expr && x.head === :call && callee_or_nothing(sc.ci, x.args[1]) in (Base.cconvert, Base.unsafe_convert) && return unwrap(x.args[3])
        return a
    end
    return [unwrap(a) for a in st.args[6:5+n]]
end

# The standard header a `ccall`ed name comes from, if it's one we know; then the output
# includes the header instead of guessing a prototype.
function foreignheader(name::AbstractString)
    (name in mathfunction || name in mathfunction .* "f" || name in mathfunction .* "l") && return "math.h"
    name in ("memset", "memcpy", "memmove", "memcmp", "strlen", "strcmp", "strcpy", "strncpy", "strcat", "strchr", "strstr") && return "string.h"
    name in ("malloc", "calloc", "realloc", "free", "abs", "labs", "llabs", "atoi", "atol", "atof", "strtod", "strtol", "rand", "srand", "exit", "abort", "qsort") && return "stdlib.h"
    name in ("printf", "puts", "putchar", "fflush", "getchar") && return "stdio.h"
    return nothing
end

# `A[i]`, `A[i, j]`: Julia's 1-based indices become 0-based.
function index(sc::Scope, A, idx)
    T = valuetype(sc, A)
    isarray(T) || throw(ArgumentError("indexing into a $T"))
    # `(A')[i, j]` read in place: the same storage with its axes the other way round, which
    # the axis model knows how to read (and to conjugate, for an adjoint of complex numbers).
    istransposed(T) && length(idx) == 2 && return access(T, value(sc, A), [subscript(sc, k) for k in idx])
    length(idx) == 1 && ndims(T) > 1 && !istransposed(T) && valuetype(sc, idx[1]) <: Integer && return value(sc, A) * linear(sc, T, idx[1])
    length(idx) == ndims(T) || throw(ArgumentError("$(length(idx)) indices into a $(ndims(T))-dimensional array"))
    return value(sc, A) * join("[$(subscript(sc, k))]" for k in idx)
end

# `A[k]` on a matrix: Julia counts through the whole array down its columns, first index
# fastest, and the C is stored by rows, so the one index is taken apart into one per
# dimension: `A[(k - 1) % m][(k - 1) / m]`. A literal `k` is taken apart here.
function linear(sc::Scope, T::Type, k)
    dims = shape(T)
    v = literal(sc, k)
    if v isa Integer
        subs = String[]
        k0 = v - 1
        for m in dims
            push!(subs, string(k0 % m))
            k0 ÷= m
        end
        return join("[$x]" for x in subs)
    end
    k0 = subscript(sc, k)
    occursin(r"^\w+$", k0) || (k0 = "($k0)")
    subs = String[]
    stride = 1
    for (d, m) in enumerate(dims)
        x = stride == 1 ? k0 : "$k0 / $stride"
        push!(subs, d == length(dims) ? x : stride == 1 ? "$x % $m" : "($x) % $m")
        stride *= m
    end
    return join("[$x]" for x in subs)
end

# A 1-based Julia index as a 0-based C subscript. The shift folds into a literal offset
# the index already has: `v[i + 1]` is `v[i]`, `v[i - 1]` is `v[i - 2]`.
function subscript(sc::Scope, k)
    k isa Integer && return string(k - 1)
    text, p = expression(sc, k)
    if p == ADD && (m = match(r"^(.*) ([+-]) (\d+)$", text)) !== nothing
        off = (m[2] == "+" ? 1 : -1) * parse(Int, m[3]) - 1
        return off == 0 ? m[1] : m[1] * (off > 0 ? " + $off" : " - $(-off)")
    end
    return (p < ADD ? "($text)" : text) * " - 1"
end

# An integer as C writes it. C has no negative literals: `-9223372036854775808` is the
# negation of a number that doesn't fit, which a compiler warns of, so the least 64-bit
# value is the name `stdint.h` gives it. An unsigned value past the signed range needs its suffix.
integer(x::Integer) = x isa Int64 && x == typemin(Int64) ? "INT64_MIN" :
                      x isa Unsigned && x > typemax(Int64) ? string(x) * "u" : string(x)

# C code for an IR value (a name or literal; use `expression` for inlined calls).
function value(sc::Scope, x)
    if x isa Core.SSAValue
        x.id in sc.inlined && return first(expression(sc, x))
        haskey(sc.expr, x.id) && return sc.expr[x.id]
        haskey(sc.pair, x.id) && throw(ArgumentError("`sincos` and `minmax` are only available destructured, `s, c = sincos(x)`, `lo, hi = minmax(a, b)` (statement $(x.id))"))
        sc.ci.code[x.id] isa GlobalRef && return value(sc, sc.ci.code[x.id])
        # The `N` of `where {N}` used as a number: known when transpiled.
        (st = sc.ci.code[x.id]; st isa Expr && st.head === :static_parameter && sc.ci.ssavaluetypes[x.id] isa Core.Const && sc.ci.ssavaluetypes[x.id].val isa Number) &&
            return value(sc, sc.ci.ssavaluetypes[x.id].val)
        sc.ci.code[x.id] isa Core.SlotNumber && return sc.names[sc.ci.code[x.id].id]   # a read inside a loop header
        throw(ArgumentError("value of statement $(x.id) is not available in C"))
    end
    if x isa Core.SlotNumber && haskey(sc.slotkinds, x.id) && isempty(sc.slotkinds[x.id].cname)
        # A spread tuple parameter used whole: gathered back into the structural struct.
        T = slottype(sc, x.id)
        structdef!(sc.prog, T)
        return "($(ctype(T))){$(join(sc.slotkinds[x.id].fields, ", "))}"
    end
    x isa Core.SlotNumber && return sc.names[x.id]
    x isa Bool            && return booltype[] === Bool ? (x ? "true" : "false") : (x ? "1" : "0")
    x isa Char            && return charliteral(x)
    x isa AbstractString  && return "\"" * cstring(x) * "\""
    x isa Integer         && return integer(x)
    x isa AbstractFloat   && return isinf(x) ? (push!(sc.headers, "math.h"); x > 0 ? "INFINITY" : "-INFINITY") :
                                    isnan(x) ? (push!(sc.headers, "math.h"); "NAN") : x isa Float32 ? replace(string(x), "f" => "e") * "f" : repr(x)
    x isa AbstractIrrational && return constant(sc, x)
    x === im              && return "I"                       # <complex.h>'s imaginary unit
    x isa Complex         && return "$(x isa ComplexF32 ? "CMPLXF" : "CMPLX")($(value(sc, real(x))), $(value(sc, imag(x))))"
    if x isa GlobalRef
        # A global the function reads: a function, type or Julia constant is itself; a
        # value of the user's becomes a global variable of the program, by name.
        v = getfield(x.mod, x.name)
        builtin(x, v) && return value(sc, v)
        g = global!(sc.prog, owner(x), x.name, v)
        # A plain global read here has no type Julia can rely on, and neither can the C;
        # `k::Float64 = 2.0` gives it one.
        g.constant || Core.get_binding_type(g.mod, g.name) !== Any ||
            throw(ArgumentError("the global $(x.name) is neither const nor typed, so its type isn't known where it is used; write `const $(x.name) = …` or `$(x.name)::T = …`"))
        return g.cname
    end
    throw(ArgumentError("unsupported value: $(repr(x))"))
end

# A character literal. Only ASCII fits C's `char`; anything else is refused rather than
# truncated. The escapes C needs are written; other non-printing characters in hex.
function charliteral(c::Char)
    isascii(c) || throw(ArgumentError("the character $(repr(c)) is not ASCII; C's char holds one byte"))
    escapes = Dict('\\' => "\\\\", '\'' => "\\'", '\n' => "\\n", '\t' => "\\t", '\r' => "\\r", '\0' => "\\0")
    return "'" * get(escapes, c, isprint(c) ? string(c) : "\\x" * string(UInt8(c), base=16, pad=2)) * "'"
end

# An irrational — `π`, `ℯ`, `Base.MathConstants.catalan`, one of the author's own made
# with `Base.@irrational` — is a macro named after it, `LEGIBLEC_PI`, `LEGIBLEC_CATALAN`,
# defined in the helper header to 128-bit precision. Under `posix`, π and ℯ are `M_PI`
# and `M_E` from `math.h` instead. The name is for the symbol the Julia wrote, never
# for a value: a double that happens to equal one is digits, as it is in the Julia.
function macroname(x::AbstractIrrational)
    posix[] && x === π && return "M_PI"
    posix[] && x === ℯ && return "M_E"
    name = "LEGIBLEC_" * uppercase(identifier(string(irrationalname(x))))
    # `φ` and `ϕ` both spell `PHI`: the second is `PHI_`. And a macro gives way to a name of
    # the author's, which outranks it (`macroavoid`, known on a build done again).
    while haskey(irrationals, name) && irrationals[name] !== x || name in macroavoid
        name *= "_"
    end
    irrationals[name] = x
    return name
end
irrationalname(x::AbstractIrrational) = x isa Irrational ? typeof(x).parameters[1] : nameof(typeof(x))
constant(sc::Scope, x::AbstractIrrational) = (posix[] && (x === π || x === ℯ) && push!(sc.headers, "math.h"); macroname(x))

# The type of a value: what inference says, except that an array whose size the IR
# doesn't know is given as the shaped stand-in the transpiler tracks for it.
function valuetype(sc::Scope, x)
    if x isa Core.SSAValue && !haskey(sc.shapes, x.id) && sc.ci.code[x.id] isa GlobalRef
        g = sc.ci.code[x.id]
        v = getfield(g.mod, g.name)
        v isa AbstractArray && return globaltype(v)      # a global array's size is its value's
    end
    x isa Core.SSAValue   && return get(sc.shapes, x.id, widen(sc.ci.ssavaluetypes[x.id]))
    x isa Core.SlotNumber && return get(sc.slotshapes, x.id, widen(sc.ci.slottypes[x.id]))
    x isa GlobalRef       && return globaltype(getfield(x.mod, x.name))
    return typeof(x)
end

# The function object a call refers to. In unoptimized IR the callee is usually an
# SSA value whose statement is a GlobalRef.
function callee(ci, x)
    if x isa Core.SSAValue
        t = ci.ssavaluetypes[x.id]
        t isa Core.Const && (t.val isa Function || t.val isa Type) && return plain(t.val)
        return callee(ci, ci.code[x.id])
    end
    x isa GlobalRef     && return plain(getfield(x.mod, x.name))
    # The function itself: how a method with a default argument, `agm(x, y, e=5)`, calls the
    # long one from the short one Julia makes for it, `agm(x, y) = agm(x, y, 5)`.
    x isa Core.SlotNumber && x.id == 1 && ci.slottypes[1] isa Core.Const && ci.slottypes[1].val isa Function && return ci.slottypes[1].val
    x isa Expr && x.head === :call && ci.ssavaluetypes !== nothing && return throw(ArgumentError("unsupported callee: $x"))
    (x isa Function || x isa Type || x isa Colon) && return x
    throw(ArgumentError("unsupported callee: $x"))
end

# `@fastmath x * y + sqrt(x)` calls `mul_fast`, `add_fast`, `sqrt_fast`: the same functions
# with leave to reorder, which in C is the compiler's setting and not the program's text.
const fastnames = Dict(:add => :+, :sub => :-, :mul => :*, :div => :/, :rem => :rem, :pow => :^, :eq => :(==), :ne => :!=,
                       :lt => :<, :le => :<=, :gt => :>, :ge => :>=)
function plain(f)
    f isa Function && parentmodule(f) === Base.FastMath && endswith(string(nameof(f)), "_fast") || return f
    name = Symbol(string(nameof(f))[1:end-5])
    name = get(fastnames, name, name)
    return isdefined(Base, name) ? getfield(Base, name) : f
end

# A C variable has one type, so a Julia variable assigned values of more than one has
# to be settled: a union of numbers widens to the one that holds them all — `s = 0`
# then `s += x` on floats is `double s = 0.0`, `z = 0` then `z = z^2 + c` on a complex
# `c` is `double complex z = 0`, which is what a C programmer declares and the same
# numbers Julia holds — and anything else, a scalar rebound to a matrix, a float to a
# string, is refused by name and line: Julia can't tell whether the author meant one
# variable or two, so neither can the C.
function onetype!(sc::Scope)
    ci = sc.ci
    for s in ci.nargs+1:length(ci.slottypes)
        T = ci.slottypes[s]
        T isa Union || continue
        # Julia's own slots — a `for`'s iterator state, a `#temp#` — aren't C variables.
        (s in sc.hidden || startswith(string(ci.slotnames[s]), "#")) && continue
        members = Base.uniontypes(T)
        if all(M -> M isa DataType && M <: Number && isconcretetype(M), members) && !(settle(T) isa Union)
            sc.slotshapes[s] = settle(T)                    # the override `slottype` reads
            continue
        end
        # Arrays of one shape spelled by different types (a sized `Vector`, an `SVector`)
        # are one variable already: the shape tracking at the first store settles them.
        all(M -> M isa DataType && M <: AbstractArray, members) && continue
        at = [(widen(ci.ssavaluetypes[k]), sc.stmtline[k]) for k in eachindex(ci.code) if assigns(ci.code[k], s)]
        spell(M) = isarray(M) && shape(M) !== nothing ? describe(M) : string(M)
        listed = join(("$(spell(M)) at line $l" for (M, l) in at), ", ")
        throw(ArgumentError("the variable `$(ci.slotnames[s])` is assigned values of different types ($listed); a C variable has one type, so give each its own name"))
    end
end

# Inference wraps known constants as Core.Const and partially-known structs as
# Core.PartialStruct; we only want the type.
widen(t) = settle(normalize(t isa Core.Const ? typeof(t.val) :
                            t isa Core.PartialStruct ? t.typ :
                            t isa Type ? t : throw(ArgumentError("unsupported type lattice element: $t"))))

# A union of numbers is the one number type that holds them all, wherever it shows up: a
# widened variable read into a value, `a + 1` on such a variable. Other unions pass, to
# be refused where they land with a message that knows what they are (`onetype!`,
# `returntype`).
function settle(T)
    T isa Union || return T
    members = Base.uniontypes(T)
    all(M -> M isa DataType && M <: Number && isconcretetype(M), members) || return T
    P = promote_type(members...)
    # The one that holds them all: Julia's promotion of `Int64` and `UInt64` is `UInt64`, which
    # doesn't hold -1. Such a union stays a union, and is refused by name where it is met.
    holds(M) = !(P <: Integer && M <: Integer) || M === Bool || (P <: Signed ? (M <: Signed ? sizeof(M) <= sizeof(P) : sizeof(M) < sizeof(P)) : M <: Unsigned)
    return all(holds, members) ? P : T
end
